INSERT INTO public."Ayah" (id, number, "surahNumber", "textOthmani", "textSimple") VALUES
('s71a1', 1, 71, ' إِنَّآ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَن يَأْتِيَهُمْ عَذَابٌ أَلِيمٌ', 'اِنَّاۤ اَرۡسَلۡنَا نُوۡحًا اِلٰى قَوۡمِهٖۤ اَنۡ اَنۡذِرۡ قَوۡمَكَ مِنۡ قَبۡلِ اَنۡ يَّاۡتِيَهُمۡ عَذَابٌ اَلِيۡمٌ‏'),
('s71a2', 2, 71, 'قَالَ يَـٰقَوْمِ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ', 'قَالَ يٰقَوۡمِ اِنِّىۡ لَـكُمۡ نَذِيۡرٌ مُّبِيۡنٌۙ‏'),
('s71a3', 3, 71, 'أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ', 'اَنِ اعۡبُدُوا اللّٰهَ وَاتَّقُوۡهُ وَاَطِيۡعُوۡنِۙ‏'),
('s71a4', 4, 71, 'يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرْكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى ۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُ ۖ لَوْ كُنتُمْ تَعْلَمُونَ', 'يَغۡفِرۡ لَـكُمۡ مِّنۡ ذُنُوۡبِكُمۡ وَيُؤَخِّرۡكُمۡ اِلٰٓى اَجَلٍ مُّسَمًّى​ؕ اِنَّ اَجَلَ اللّٰهِ اِذَا جَآءَ لَا يُؤَخَّرُ​​ۘ لَوۡ كُنۡتُمۡ تَعۡلَمُوۡنَ‏'),
('s71a5', 5, 71, 'قَالَ رَبِّ إِنِّى دَعَوْتُ قَوْمِى لَيْلًا وَنَهَارًا', 'قَالَ رَبِّ اِنِّىۡ دَعَوۡتُ قَوۡمِىۡ لَيۡلًا وَّنَهَارًا ۙ‏'),
('s71a6', 6, 71, 'فَلَمْ يَزِدْهُمْ دُعَآءِىٓ إِلَّا فِرَارًا', 'فَلَمۡ يَزِدۡهُمۡ دُعَآءِىۡۤ اِلَّا فِرَارًا‏'),
('s71a7', 7, 71, 'وَإِنِّى كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُوٓا۟ أَصَـٰبِعَهُمْ فِىٓ ءَاذَانِهِمْ وَٱسْتَغْشَوْا۟ ثِيَابَهُمْ وَأَصَرُّوا۟ وَٱسْتَكْبَرُوا۟ ٱسْتِكْبَارًا', 'وَاِنِّىۡ كُلَّمَا دَعَوۡتُهُمۡ لِتَغۡفِرَ لَهُمۡ جَعَلُوۡۤا اَصَابِعَهُمۡ فِىۡۤ اٰذَانِهِمۡ وَاسۡتَغۡشَوۡا ثِيَابَهُمۡ وَاَصَرُّوۡا وَاسۡتَكۡبَرُوا اسۡتِكۡبَارًا​ ۚ‏'),
('s71a8', 8, 71, 'ثُمَّ إِنِّى دَعَوْتُهُمْ جِهَارًا', 'ثُمَّ اِنِّىۡ دَعَوۡتُهُمۡ جِهَارًا ۙ‏'),
('s71a9', 9, 71, 'ثُمَّ إِنِّىٓ أَعْلَنتُ لَهُمْ وَأَسْرَرْتُ لَهُمْ إِسْرَارًا', 'ثُمَّ اِنِّىۡۤ اَعۡلَـنۡتُ لَهُمۡ وَاَسۡرَرۡتُ لَهُمۡ اِسۡرَارًا ۙ‏'),
('s71a10', 10, 71, 'فَقُلْتُ ٱسْتَغْفِرُوا۟ رَبَّكُمْ إِنَّهُۥ كَانَ غَفَّارًا', 'فَقُلۡتُ اسۡتَغۡفِرُوۡا رَبَّكُمۡؕ اِنَّهٗ كَانَ غَفَّارًا ۙ‏'),
('s71a11', 11, 71, 'يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا', 'يُّرۡسِلِ السَّمَآءَ عَلَيۡكُمۡ مِّدۡرَارًا ۙ‏'),
('s71a12', 12, 71, 'وَيُمْدِدْكُم بِأَمْوَٰلٍ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّـٰتٍ وَيَجْعَل لَّكُمْ أَنْهَـٰرًا', 'وَّيُمۡدِدۡكُمۡ بِاَمۡوَالٍ وَّبَنِيۡنَ وَيَجۡعَلۡ لَّـكُمۡ جَنّٰتٍ وَّيَجۡعَلۡ لَّـكُمۡ اَنۡهٰرًا ؕ‏'),
('s71a13', 13, 71, 'مَّا لَكُمْ لَا تَرْجُونَ لِلَّهِ وَقَارًا', 'مَا لَـكُمۡ لَا تَرۡجُوۡنَ لِلّٰهِ وَقَارًا​ ۚ‏'),
('s71a14', 14, 71, 'وَقَدْ خَلَقَكُمْ أَطْوَارًا', 'وَقَدۡ خَلَقَكُمۡ اَطۡوَارًا‏'),
('s71a15', 15, 71, 'أَلَمْ تَرَوْا۟ كَيْفَ خَلَقَ ٱللَّهُ سَبْعَ سَمَـٰوَٰتٍ طِبَاقًا', 'اَلَمۡ تَرَوۡا كَيۡفَ خَلَقَ اللّٰهُ سَبۡعَ سَمٰوٰتٍ طِبَاقًا ۙ‏'),
('s71a16', 16, 71, 'وَجَعَلَ ٱلْقَمَرَ فِيهِنَّ نُورًا وَجَعَلَ ٱلشَّمْسَ سِرَاجًا', 'وَّجَعَلَ الۡقَمَرَ فِيۡهِنَّ نُوۡرًا ۙ وَّجَعَلَ الشَّمۡسَ سِرَاجًا‏'),
('s71a17', 17, 71, 'وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلْأَرْضِ نَبَاتًا', 'وَاللّٰهُ اَنۡۢبَتَكُمۡ مِّنَ الۡاَرۡضِ نَبَاتًا ۙ‏'),
('s71a18', 18, 71, 'ثُمَّ يُعِيدُكُمْ فِيهَا وَيُخْرِجُكُمْ إِخْرَاجًا', 'ثُمَّ يُعِيۡدُكُمۡ فِيۡهَا وَيُخۡرِجُكُمۡ اِخۡرَاجًا‏'),
('s71a19', 19, 71, 'وَٱللَّهُ جَعَلَ لَكُمُ ٱلْأَرْضَ بِسَاطًا', 'وَاللّٰهُ جَعَلَ لَـكُمُ الۡاَرۡضَ بِسَاطًا ۙ‏'),
('s71a20', 20, 71, 'لِّتَسْلُكُوا۟ مِنْهَا سُبُلًا فِجَاجًا', 'لِّـتَسۡلُكُوۡا مِنۡهَا سُبُلًا فِجَاجًا‏'),
('s71a21', 21, 71, 'قَالَ نُوحٌ رَّبِّ إِنَّهُمْ عَصَوْنِى وَٱتَّبَعُوا۟ مَن لَّمْ يَزِدْهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارًا', 'قَالَ نُوۡحٌ رَّبِّ اِنَّهُمۡ عَصَوۡنِىۡ وَاتَّبَعُوۡا مَنۡ لَّمۡ يَزِدۡهُ مَالُهٗ وَوَلَدُهٗۤ اِلَّا خَسَارًا​ ۚ‏'),
('s71a22', 22, 71, 'وَمَكَرُوا۟ مَكْرًا كُبَّارًا', 'وَمَكَرُوۡا مَكۡرًا كُبَّارًا​ ۚ‏'),
('s71a23', 23, 71, 'وَقَالُوا۟ لَا تَذَرُنَّ ءَالِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّا وَلَا سُوَاعًا وَلَا يَغُوثَ وَيَعُوقَ وَنَسْرًا', 'وَ قَالُوۡا لَا تَذَرُنَّ اٰلِهَتَكُمۡ وَلَا تَذَرُنَّ وَدًّا وَّلَا سُوَاعًا  ۙ وَّ لَا يَغُوۡثَ وَيَعُوۡقَ وَنَسۡرًا​ ۚ‏'),
('s71a24', 24, 71, 'وَقَدْ أَضَلُّوا۟ كَثِيرًا ۖ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا ضَلَـٰلًا', 'وَقَدۡ اَضَلُّوۡا كَثِيۡرًا​ ​ ۚ وَلَا تَزِدِ الظّٰلِمِيۡنَ اِلَّا ضَلٰلًا‏ ﻿﻿'),
('s71a25', 25, 71, 'مِّمَّا خَطِيٓـَٔـٰتِهِمْ أُغْرِقُوا۟ فَأُدْخِلُوا۟ نَارًا فَلَمْ يَجِدُوا۟ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارًا', 'مِّمَّا خَطِٓيْئٰتِهِمۡ اُغۡرِقُوۡا فَاُدۡخِلُوۡا نَارًا  ۙ فَلَمۡ يَجِدُوۡا لَهُمۡ مِّنۡ دُوۡنِ اللّٰهِ اَنۡصَارًا‏'),
('s71a26', 26, 71, 'وَقَالَ نُوحٌ رَّبِّ لَا تَذَرْ عَلَى ٱلْأَرْضِ مِنَ ٱلْكَـٰفِرِينَ دَيَّارًا', 'وَ قَالَ نُوۡحٌ رَّبِّ لَا تَذَرۡ عَلَى الۡاَرۡضِ مِنَ الۡكٰفِرِيۡنَ دَيَّارًا‏ ﻿﻿'),
('s71a27', 27, 71, 'إِنَّكَ إِن تَذَرْهُمْ يُضِلُّوا۟ عِبَادَكَ وَلَا يَلِدُوٓا۟ إِلَّا فَاجِرًا كَفَّارًا', 'اِنَّكَ اِنۡ تَذَرۡهُمۡ يُضِلُّوۡا عِبَادَكَ وَلَا يَلِدُوۡۤا اِلَّا فَاجِرًا كَفَّارًا‏'),
('s71a28', 28, 71, 'رَّبِّ ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا تَبَارًۢا', 'رَبِّ اغۡفِرۡلِىۡ وَلِـوَالِدَىَّ وَلِمَنۡ دَخَلَ بَيۡتِىَ مُؤۡمِنًا وَّلِلۡمُؤۡمِنِيۡنَ وَالۡمُؤۡمِنٰتِؕ وَلَا تَزِدِ الظّٰلِمِيۡنَ اِلَّا تَبَارًا‏'),
('s72a1', 1, 72, ' قُلْ أُوحِىَ إِلَىَّ أَنَّهُ ٱسْتَمَعَ نَفَرٌ مِّنَ ٱلْجِنِّ فَقَالُوٓا۟ إِنَّا سَمِعْنَا قُرْءَانًا عَجَبًا', 'قُلۡ اُوۡحِىَ اِلَىَّ اَنَّهُ اسۡتَمَعَ نَفَرٌ مِّنَ الۡجِنِّ فَقَالُوۡۤا اِنَّا سَمِعۡنَا قُرۡاٰنًاعَجَبًا ۙ‏'),
('s72a2', 2, 72, 'يَهْدِىٓ إِلَى ٱلرُّشْدِ فَـَٔامَنَّا بِهِۦ ۖ وَلَن نُّشْرِكَ بِرَبِّنَآ أَحَدًا', 'يَّهۡدِىۡۤ اِلَى الرُّشۡدِ فَاٰمَنَّا بِهٖ​ ؕ وَلَنۡ نُّشۡرِكَ بِرَبِّنَاۤ اَحَدًا ۙ‏'),
('s72a3', 3, 72, 'وَأَنَّهُۥ تَعَـٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَـٰحِبَةً وَلَا وَلَدًا', 'وَّاَنَّهٗ تَعٰلٰى جَدُّ رَبِّنَا مَا اتَّخَذَ صَاحِبَةً وَّلَا وَلَدًا ۙ‏ ﻿﻿'),
('s72a4', 4, 72, 'وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطًا', 'وَّ اَنَّهٗ كَانَ يَقُوۡلُ سَفِيۡهُنَا عَلَى اللّٰهِ شَطَطًا ۙ‏'),
('s72a5', 5, 72, 'وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلْإِنسُ وَٱلْجِنُّ عَلَى ٱللَّهِ كَذِبًا', 'وَّاَنَّا ظَنَنَّاۤ اَنۡ لَّنۡ تَقُوۡلَ الۡاِنۡسُ وَالۡجِنُّ عَلَى اللّٰهِ كَذِبًا ۙ‏'),
('s72a6', 6, 72, 'وَأَنَّهُۥ كَانَ رِجَالٌ مِّنَ ٱلْإِنسِ يَعُوذُونَ بِرِجَالٍ مِّنَ ٱلْجِنِّ فَزَادُوهُمْ رَهَقًا', 'وَّاَنَّهٗ كَانَ رِجَالٌ مِّنَ الۡاِنۡسِ يَعُوۡذُوۡنَ بِرِجَالٍ مِّنَ الۡجِنِّ فَزَادُوۡهُمۡ رَهَقًا ۙ‏'),
('s72a7', 7, 72, 'وَأَنَّهُمْ ظَنُّوا۟ كَمَا ظَنَنتُمْ أَن لَّن يَبْعَثَ ٱللَّهُ أَحَدًا', 'وَّاَنَّهُمۡ ظَنُّوۡا كَمَا ظَنَنۡتُمۡ اَنۡ لَّنۡ يَّبۡعَثَ اللّٰهُ اَحَدًا ۙ‏'),
('s72a8', 8, 72, 'وَأَنَّا لَمَسْنَا ٱلسَّمَآءَ فَوَجَدْنَـٰهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا', 'وَّاَنَّا لَمَسۡنَا السَّمَآءَ فَوَجَدۡنٰهَا مُلِئَتۡ حَرَسًا شَدِيۡدًا وَّشُهُبًا ۙ‏'),
('s72a9', 9, 72, 'وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَـٰعِدَ لِلسَّمْعِ ۖ فَمَن يَسْتَمِعِ ٱلْـَٔانَ يَجِدْ لَهُۥ شِهَابًا رَّصَدًا', 'وَّاَنَّا كُنَّا نَقۡعُدُ مِنۡهَا مَقَاعِدَ لِلسَّمۡعِ​ ؕ فَمَنۡ يَّسۡتَمِعِ الۡاٰنَ يَجِدۡ لَهٗ شِهَابًا رَّصَدًا ۙ‏'),
('s72a10', 10, 72, 'وَأَنَّا لَا نَدْرِىٓ أَشَرٌّ أُرِيدَ بِمَن فِى ٱلْأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا', 'وَّاَنَّا لَا نَدۡرِىۡۤ اَشَرٌّ اُرِيۡدَ بِمَنۡ فِى الۡاَرۡضِ اَمۡ اَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدًا ۙ‏'),
('s72a11', 11, 72, 'وَأَنَّا مِنَّا ٱلصَّـٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَ ۖ كُنَّا طَرَآئِقَ قِدَدًا', 'وَّاَنَّا مِنَّا الصّٰلِحُوۡنَ وَمِنَّا دُوۡنَ ذٰلِكَ​ؕ كُنَّا طَرَآٮِٕقَ قِدَدًا ۙ‏'),
('s72a12', 12, 72, 'وَأَنَّا ظَنَنَّآ أَن لَّن نُّعْجِزَ ٱللَّهَ فِى ٱلْأَرْضِ وَلَن نُّعْجِزَهُۥ هَرَبًا', 'وَّاَنَّا ظَنَنَّاۤ اَنۡ لَّنۡ نُّعۡجِزَ اللّٰهَ فِى الۡاَرۡضِ وَلَنۡ نُّعۡجِزَهٗ هَرَبًا ۙ‏'),
('s72a13', 13, 72, 'وَأَنَّا لَمَّا سَمِعْنَا ٱلْهُدَىٰٓ ءَامَنَّا بِهِۦ ۖ فَمَن يُؤْمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخْسًا وَلَا رَهَقًا', 'وَّاَنَّا لَمَّا سَمِعۡنَا الۡهُدٰٓى اٰمَنَّا بِهٖ​ ؕ فَمَنۡ يُّؤۡمِنۡۢ بِرَبِّهٖ فَلَا يَخَافُ بَخۡسًا وَّلَا رَهَقًا ۙ‏'),
('s72a14', 14, 72, 'وَأَنَّا مِنَّا ٱلْمُسْلِمُونَ وَمِنَّا ٱلْقَـٰسِطُونَ ۖ فَمَنْ أَسْلَمَ فَأُو۟لَـٰٓئِكَ تَحَرَّوْا۟ رَشَدًا', 'وَّاَنَّا مِنَّا الۡمُسۡلِمُوۡنَ وَمِنَّا الۡقٰسِطُوۡنَ​ؕ فَمَنۡ اَسۡلَمَ فَاُولٰٓٮِٕكَ تَحَرَّوۡا رَشَدًا‏'),
('s72a15', 15, 72, 'وَأَمَّا ٱلْقَـٰسِطُونَ فَكَانُوا۟ لِجَهَنَّمَ حَطَبًا', 'وَاَمَّا الۡقٰسِطُوۡنَ فَكَانُوۡا لِجَهَنَّمَ حَطَبًا ۙ‏'),
('s72a16', 16, 72, 'وَأَلَّوِ ٱسْتَقَـٰمُوا۟ عَلَى ٱلطَّرِيقَةِ لَأَسْقَيْنَـٰهُم مَّآءً غَدَقًا', 'وَّاَنْ لَّوِ اسۡتَقَامُوۡا عَلَى الطَّرِيۡقَةِ لَاَسۡقَيۡنٰهُمۡ مَّآءً غَدَقًا ۙ‏'),
('s72a17', 17, 72, 'لِّنَفْتِنَهُمْ فِيهِ ۚ وَمَن يُعْرِضْ عَن ذِكْرِ رَبِّهِۦ يَسْلُكْهُ عَذَابًا صَعَدًا', 'لِّنَفۡتِنَهُمۡ فِيۡهِ​ ؕ وَمَنۡ يُّعۡرِضۡ عَنۡ ذِكۡرِ رَبِّهٖ يَسۡلُكۡهُ عَذَابًا صَعَدًا ۙ‏'),
('s72a18', 18, 72, 'وَأَنَّ ٱلْمَسَـٰجِدَ لِلَّهِ فَلَا تَدْعُوا۟ مَعَ ٱللَّهِ أَحَدًا', 'وَّاَنَّ الۡمَسٰجِدَ لِلّٰهِ فَلَا تَدۡعُوۡا مَعَ اللّٰهِ اَحَدًا ۙ‏'),
('s72a19', 19, 72, 'وَأَنَّهُۥ لَمَّا قَامَ عَبْدُ ٱللَّهِ يَدْعُوهُ كَادُوا۟ يَكُونُونَ عَلَيْهِ لِبَدًا', 'وَّاَنَّهٗ لَمَّا قَامَ عَبۡدُ اللّٰهِ يَدۡعُوۡهُ كَادُوۡا يَكُوۡنُوۡنَ عَلَيۡهِ لِبَدًا ؕ‏'),
('s72a20', 20, 72, 'قُلْ إِنَّمَآ أَدْعُوا۟ رَبِّى وَلَآ أُشْرِكُ بِهِۦٓ أَحَدًا', 'قُلۡ اِنَّمَاۤ اَدۡعُوۡا رَبِّىۡ وَلَاۤ اُشۡرِكُ بِهٖۤ اَحَدًا‏'),
('s72a21', 21, 72, 'قُلْ إِنِّى لَآ أَمْلِكُ لَكُمْ ضَرًّا وَلَا رَشَدًا', 'قُلۡ اِنِّىۡ لَاۤ اَمۡلِكُ لَـكُمۡ ضَرًّا وَّلَا رَشَدًا‏'),
('s72a22', 22, 72, 'قُلْ إِنِّى لَن يُجِيرَنِى مِنَ ٱللَّهِ أَحَدٌ وَلَنْ أَجِدَ مِن دُونِهِۦ مُلْتَحَدًا', 'قُلۡ اِنِّىۡ لَنۡ يُّجِيۡرَنِىۡ مِنَ اللّٰهِ اَحَدٌ  ۙ وَّلَنۡ اَجِدَ مِنۡ دُوۡنِهٖ مُلۡتَحَدًا ۙ‏'),
('s72a23', 23, 72, 'إِلَّا بَلَـٰغًا مِّنَ ٱللَّهِ وَرِسَـٰلَـٰتِهِۦ ۚ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ أَبَدًا', 'اِلَّا بَلٰغًا مِّنَ اللّٰهِ وَرِسٰلٰتِهٖ​ ؕ وَمَنۡ يَّعۡصِ اللّٰهَ وَرَسُوۡلَهٗ فَاِنَّ لَهٗ نَارَ جَهَنَّمَ خٰلِدِيۡنَ فِيۡهَاۤ اَبَدًا ؕ‏'),
('s72a24', 24, 72, 'حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِرًا وَأَقَلُّ عَدَدًا', 'حَتّٰٓى اِذَا رَاَوۡا مَا يُوۡعَدُوۡنَ فَسَيَعۡلَمُوۡنَ مَنۡ اَضۡعَفُ نَاصِرًا وَّاَقَلُّ عَدَدًا‏'),
('s72a25', 25, 72, 'قُلْ إِنْ أَدْرِىٓ أَقَرِيبٌ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُۥ رَبِّىٓ أَمَدًا', 'قُلۡ اِنۡ اَدۡرِىۡۤ اَقَرِيۡبٌ مَّا تُوۡعَدُوۡنَ اَمۡ يَجۡعَلُ لَهٗ رَبِّىۡۤ اَمَدًا‏'),
('s72a26', 26, 72, 'عَـٰلِمُ ٱلْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِهِۦٓ أَحَدًا', 'عٰلِمُ الۡغَيۡبِ فَلَا يُظۡهِرُ عَلٰى غَيۡبِهٖۤ اَحَدًا ۙ‏'),
('s72a27', 27, 72, 'إِلَّا مَنِ ٱرْتَضَىٰ مِن رَّسُولٍ فَإِنَّهُۥ يَسْلُكُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ رَصَدًا', 'اِلَّا مَنِ ارۡتَضٰى مِنۡ رَّسُوۡلٍ فَاِنَّهٗ يَسۡلُكُ مِنۡۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهٖ رَصَدًا ۙ‏'),
('s72a28', 28, 72, 'لِّيَعْلَمَ أَن قَدْ أَبْلَغُوا۟ رِسَـٰلَـٰتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصَىٰ كُلَّ شَىْءٍ عَدَدًۢا', 'لِّيَـعۡلَمَ اَنۡ قَدۡ اَبۡلَغُوۡا رِسٰلٰتِ رَبِّهِمۡ وَاَحَاطَ بِمَا لَدَيۡهِمۡ وَاَحۡصٰى كُلَّ شَىۡءٍ عَدَدًا‏'),
('s73a1', 1, 73, ' يَـٰٓأَيُّهَا ٱلْمُزَّمِّلُ', 'يٰۤاَيُّهَا الۡمُزَّمِّلُۙ‏'),
('s73a2', 2, 73, 'قُمِ ٱلَّيْلَ إِلَّا قَلِيلًا', 'قُمِ الَّيۡلَ اِلَّا قَلِيۡلًا ۙ‏'),
('s73a3', 3, 73, 'نِّصْفَهُۥٓ أَوِ ٱنقُصْ مِنْهُ قَلِيلًا', 'نِّصۡفَهٗۤ اَوِ انْقُصۡ مِنۡهُ قَلِيۡلًا ۙ‏'),
('s73a4', 4, 73, 'أَوْ زِدْ عَلَيْهِ وَرَتِّلِ ٱلْقُرْءَانَ تَرْتِيلًا', 'اَوۡ زِدۡ عَلَيۡهِ وَرَتِّلِ الۡقُرۡاٰنَ تَرۡتِيۡلًا ؕ‏'),
('s73a5', 5, 73, 'إِنَّا سَنُلْقِى عَلَيْكَ قَوْلًا ثَقِيلًا', 'اِنَّا سَنُلۡقِىۡ عَلَيۡكَ قَوۡلًا ثَقِيۡلًا‏'),
('s73a6', 6, 73, 'إِنَّ نَاشِئَةَ ٱلَّيْلِ هِىَ أَشَدُّ وَطْـًٔا وَأَقْوَمُ قِيلًا', 'اِنَّ نَاشِئَةَ الَّيۡلِ هِىَ اَشَدُّ وَطۡـاً وَّاَقۡوَمُ قِيۡلًا ؕ‏'),
('s73a7', 7, 73, 'إِنَّ لَكَ فِى ٱلنَّهَارِ سَبْحًا طَوِيلًا', 'اِنَّ لَـكَ فِى النَّهَارِ سَبۡحًا طَوِيۡلًا ؕ‏'),
('s73a8', 8, 73, 'وَٱذْكُرِ ٱسْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا', 'وَاذۡكُرِ اسۡمَ رَبِّكَ وَتَبَتَّلۡ اِلَيۡهِ تَبۡتِيۡلًا ؕ‏'),
('s73a9', 9, 73, 'رَّبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ لَآ إِلَـٰهَ إِلَّا هُوَ فَٱتَّخِذْهُ وَكِيلًا', 'رَبُّ الۡمَشۡرِقِ وَالۡمَغۡرِبِ لَاۤ اِلٰهَ اِلَّا هُوَ فَاتَّخِذۡهُ وَكِيۡلًا‏ ﻿﻿'),
('s73a10', 10, 73, 'وَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱهْجُرْهُمْ هَجْرًا جَمِيلًا', 'وَاصۡبِرۡ عَلٰى مَا يَقُوۡلُوۡنَ وَاهۡجُرۡهُمۡ هَجۡرًا جَمِيۡلًا‏'),
('s73a11', 11, 73, 'وَذَرْنِى وَٱلْمُكَذِّبِينَ أُو۟لِى ٱلنَّعْمَةِ وَمَهِّلْهُمْ قَلِيلًا', 'وَذَرۡنِىۡ وَالۡمُكَذِّبِيۡنَ اُولِى النَّعۡمَةِ وَمَهِّلۡهُمۡ قَلِيۡلًا‏ ﻿﻿'),
('s73a12', 12, 73, 'إِنَّ لَدَيْنَآ أَنكَالًا وَجَحِيمًا', 'اِنَّ لَدَيۡنَاۤ اَنۡـكَالًا وَّجَحِيۡمًا ۙ‏'),
('s73a13', 13, 73, 'وَطَعَامًا ذَا غُصَّةٍ وَعَذَابًا أَلِيمًا', 'وَّطَعَامًا ذَا غُصَّةٍ وَّعَذَابًا اَلِيۡمًا‏'),
('s73a14', 14, 73, 'يَوْمَ تَرْجُفُ ٱلْأَرْضُ وَٱلْجِبَالُ وَكَانَتِ ٱلْجِبَالُ كَثِيبًا مَّهِيلًا', 'يَوۡمَ تَرۡجُفُ الۡاَرۡضُ وَالۡجِبَالُ وَكَانَتِ الۡجِبَالُ كَثِيۡبًا مَّهِيۡلًا‏ ﻿﻿'),
('s73a15', 15, 73, 'إِنَّآ أَرْسَلْنَآ إِلَيْكُمْ رَسُولًا شَـٰهِدًا عَلَيْكُمْ كَمَآ أَرْسَلْنَآ إِلَىٰ فِرْعَوْنَ رَسُولًا', 'اِنَّاۤ اَرۡسَلۡنَاۤ اِلَيۡكُمۡ رَسُوۡلًا ۙ شَاهِدًا عَلَيۡكُمۡ كَمَاۤ اَرۡسَلۡنَاۤ اِلٰى فِرۡعَوۡنَ رَسُوۡلًا ؕ‏'),
('s73a16', 16, 73, 'فَعَصَىٰ فِرْعَوْنُ ٱلرَّسُولَ فَأَخَذْنَـٰهُ أَخْذًا وَبِيلًا', 'فَعَصٰى فِرۡعَوۡنُ الرَّسُوۡلَ فَاَخَذۡنٰهُ اَخۡذًا وَّبِيۡلًا‏'),
('s73a17', 17, 73, 'فَكَيْفَ تَتَّقُونَ إِن كَفَرْتُمْ يَوْمًا يَجْعَلُ ٱلْوِلْدَٰنَ شِيبًا', 'فَكَيۡفَ تَتَّقُوۡنَ اِنۡ كَفَرۡتُمۡ يَوۡمًا يَّجۡعَلُ الۡوِلۡدَانَ شِيۡبَا  ۖ‏'),
('s73a18', 18, 73, 'ٱلسَّمَآءُ مُنفَطِرٌۢ بِهِۦ ۚ كَانَ وَعْدُهُۥ مَفْعُولًا', 'اۨلسَّمَآءُ مُنۡفَطِرٌ ۢ بِهٖ​ؕ كَانَ وَعۡدُهٗ مَفۡعُوۡلًا‏'),
('s73a19', 19, 73, 'إِنَّ هَـٰذِهِۦ تَذْكِرَةٌ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', 'اِنَّ هٰذِهٖ تَذۡكِرَةٌ ​ ۚ فَمَنۡ شَآءَ اتَّخَذَ اِلٰى رَبِّهٖ سَبِيۡلًا‏ ﻿﻿'),
('s73a20', 20, 73, '۞ إِنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنَىٰ مِن ثُلُثَىِ ٱلَّيْلِ وَنِصْفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٌ مِّنَ ٱلَّذِينَ مَعَكَ ۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيْلَ وَٱلنَّهَارَ ۚ عَلِمَ أَن لَّن تُحْصُوهُ فَتَابَ عَلَيْكُمْ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنَ ٱلْقُرْءَانِ ۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرْضَىٰ ۙ وَءَاخَرُونَ يَضْرِبُونَ فِى ٱلْأَرْضِ يَبْتَغُونَ مِن فَضْلِ ٱللَّهِ ۙ وَءَاخَرُونَ يُقَـٰتِلُونَ فِى سَبِيلِ ٱللَّهِ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنْهُ ۚ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيْرًا وَأَعْظَمَ أَجْرًا ۚ وَٱسْتَغْفِرُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌۢ', 'اِنَّ رَبَّكَ يَعۡلَمُ اَنَّكَ تَقُوۡمُ اَدۡنىٰ مِنۡ ثُلُثَىِ الَّيۡلِ وَ نِصۡفَهٗ وَثُلُثَهٗ وَطَآٮِٕفَةٌ مِّنَ الَّذِيۡنَ مَعَكَ​ؕ وَاللّٰهُ يُقَدِّرُ الَّيۡلَ وَالنَّهَارَ​ؕ عَلِمَ اَنۡ لَّنۡ تُحۡصُوۡهُ فَتَابَ عَلَيۡكُمۡ​ فَاقۡرَءُوۡا مَا تَيَسَّرَ مِنَ الۡقُرۡاٰنِ​ؕ عَلِمَ اَنۡ سَيَكُوۡنُ مِنۡكُمۡ مَّرۡضٰى​ۙ وَاٰخَرُوۡنَ يَضۡرِبُوۡنَ فِى الۡاَرۡضِ يَبۡتَغُوۡنَ مِنۡ فَضۡلِ اللّٰهِ​ۙ وَاٰخَرُوۡنَ يُقَاتِلُوۡنَ فِىۡ سَبِيۡلِ اللّٰهِ ۖ فَاقۡرَءُوۡا مَا تَيَسَّرَ مِنۡهُ​ ۙ وَاَقِيۡمُوا الصَّلٰوةَ وَاٰتُوا الزَّكٰوةَ وَاَقۡرِضُوا اللّٰهَ قَرۡضًا حَسَنًا​ ؕ وَمَا تُقَدِّمُوۡا لِاَنۡفُسِكُمۡ مِّنۡ خَيۡرٍ تَجِدُوۡهُ عِنۡدَ اللّٰهِ هُوَ خَيۡرًا وَّاَعۡظَمَ اَجۡرًا​ ؕ وَاسۡتَغۡفِرُوا اللّٰهَ ​ؕ اِنَّ اللّٰهَ غَفُوۡرٌ رَّحِيۡمٌ‏'),
('s74a1', 1, 74, ' يَـٰٓأَيُّهَا ٱلْمُدَّثِّرُ', 'يٰۤاَيُّهَا الۡمُدَّثِّرُۙ‏'),
('s74a2', 2, 74, 'قُمْ فَأَنذِرْ', 'قُمۡ فَاَنۡذِرۡۙ‏'),
('s74a3', 3, 74, 'وَرَبَّكَ فَكَبِّرْ', 'وَرَبَّكَ فَكَبِّرۡۙ‏'),
('s74a4', 4, 74, 'وَثِيَابَكَ فَطَهِّرْ', 'وَثِيَابَكَ فَطَهِّرۡۙ‏'),
('s74a5', 5, 74, 'وَٱلرُّجْزَ فَٱهْجُرْ', 'وَالرُّجۡزَ فَاهۡجُرۡۙ‏'),
('s74a6', 6, 74, 'وَلَا تَمْنُن تَسْتَكْثِرُ', 'وَلَا تَمۡنُنۡ تَسۡتَكۡثِرُۙ‏'),
('s74a7', 7, 74, 'وَلِرَبِّكَ فَٱصْبِرْ', 'وَ لِرَبِّكَ فَاصۡبِرۡؕ‏'),
('s74a8', 8, 74, 'فَإِذَا نُقِرَ فِى ٱلنَّاقُورِ', 'فَاِذَا نُقِرَ فِى النَّاقُوۡرِۙ‏'),
('s74a9', 9, 74, 'فَذَٰلِكَ يَوْمَئِذٍ يَوْمٌ عَسِيرٌ', 'فَذٰلِكَ يَوۡمَٮِٕذٍ يَّوۡمٌ عَسِيۡرٌۙ‏'),
('s74a10', 10, 74, 'عَلَى ٱلْكَـٰفِرِينَ غَيْرُ يَسِيرٍ', 'عَلَى الۡكٰفِرِيۡنَ غَيۡرُ يَسِيۡرٍ‏'),
('s74a11', 11, 74, 'ذَرْنِى وَمَنْ خَلَقْتُ وَحِيدًا', 'ذَرۡنِىۡ وَمَنۡ خَلَقۡتُ وَحِيۡدًا ۙ‏'),
('s74a12', 12, 74, 'وَجَعَلْتُ لَهُۥ مَالًا مَّمْدُودًا', 'وَّجَعَلۡتُ لَهٗ مَالًا مَّمۡدُوۡدًا ۙ‏'),
('s74a13', 13, 74, 'وَبَنِينَ شُهُودًا', 'وَّبَنِيۡنَ شُهُوۡدًا ۙ‏'),
('s74a14', 14, 74, 'وَمَهَّدتُّ لَهُۥ تَمْهِيدًا', 'وَّمَهَّدتُّ لَهٗ تَمۡهِيۡدًا ۙ‏'),
('s74a15', 15, 74, 'ثُمَّ يَطْمَعُ أَنْ أَزِيدَ', 'ثُمَّ يَطۡمَعُ اَنۡ اَزِيۡدَ  ۙ‏'),
('s74a16', 16, 74, 'كَلَّآ ۖ إِنَّهُۥ كَانَ لِـَٔايَـٰتِنَا عَنِيدًا', 'كَلَّا ؕ اِنَّهٗ كَانَ لِاٰيٰتِنَا عَنِيۡدًا ؕ‏'),
('s74a17', 17, 74, 'سَأُرْهِقُهُۥ صَعُودًا', 'سَاُرۡهِقُهٗ صَعُوۡدًا ؕ‏'),
('s74a18', 18, 74, 'إِنَّهُۥ فَكَّرَ وَقَدَّرَ', 'اِنَّهٗ فَكَّرَ وَقَدَّرَۙ‏'),
('s74a19', 19, 74, 'فَقُتِلَ كَيْفَ قَدَّرَ', 'فَقُتِلَ كَيۡفَ قَدَّرَۙ‏'),
('s74a20', 20, 74, 'ثُمَّ قُتِلَ كَيْفَ قَدَّرَ', 'ثُمَّ قُتِلَ كَيۡفَ قَدَّرَۙ‏'),
('s74a21', 21, 74, 'ثُمَّ نَظَرَ', 'ثُمَّ نَظَرَۙ‏'),
('s74a22', 22, 74, 'ثُمَّ عَبَسَ وَبَسَرَ', 'ثُمَّ عَبَسَ وَبَسَرَۙ‏'),
('s74a23', 23, 74, 'ثُمَّ أَدْبَرَ وَٱسْتَكْبَرَ', 'ثُمَّ اَدۡبَرَ وَاسۡتَكۡبَرَۙ‏'),
('s74a24', 24, 74, 'فَقَالَ إِنْ هَـٰذَآ إِلَّا سِحْرٌ يُؤْثَرُ', 'فَقَالَ اِنۡ هٰذَاۤ اِلَّا سِحۡرٌ يُّؤۡثَرُۙ‏'),
('s74a25', 25, 74, 'إِنْ هَـٰذَآ إِلَّا قَوْلُ ٱلْبَشَرِ', 'اِنۡ هٰذَاۤ اِلَّا قَوۡلُ الۡبَشَرِؕ‏'),
('s74a26', 26, 74, 'سَأُصْلِيهِ سَقَرَ', 'سَاُصۡلِيۡهِ سَقَرَ‏'),
('s74a27', 27, 74, 'وَمَآ أَدْرَىٰكَ مَا سَقَرُ', 'وَمَاۤ اَدۡرٰٮكَ مَا سَقَرُؕ‏'),
('s74a28', 28, 74, 'لَا تُبْقِى وَلَا تَذَرُ', 'لَا تُبۡقِىۡ وَ لَا تَذَرُ​ۚ‏'),
('s74a29', 29, 74, 'لَوَّاحَةٌ لِّلْبَشَرِ', 'لَـوَّاحَةٌ لِّلۡبَشَرِ​ۖ​ۚ‏'),
('s74a30', 30, 74, 'عَلَيْهَا تِسْعَةَ عَشَرَ', 'عَلَيۡهَا تِسۡعَةَ عَشَرَؕ‏'),
('s74a31', 31, 74, 'وَمَا جَعَلْنَآ أَصْحَـٰبَ ٱلنَّارِ إِلَّا مَلَـٰٓئِكَةً ۙ وَمَا جَعَلْنَا عِدَّتَهُمْ إِلَّا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ لِيَسْتَيْقِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ وَيَزْدَادَ ٱلَّذِينَ ءَامَنُوٓا۟ إِيمَـٰنًا ۙ وَلَا يَرْتَابَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ وَٱلْمُؤْمِنُونَ ۙ وَلِيَقُولَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْكَـٰفِرُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلًا ۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ ۚ وَمَا هِىَ إِلَّا ذِكْرَىٰ لِلْبَشَرِ', 'وَمَا جَعَلۡنَاۤ اَصۡحٰبَ النَّارِ اِلَّا مَلٰٓٮِٕكَةً​ وَّمَا جَعَلۡنَا عِدَّتَهُمۡ اِلَّا فِتۡنَةً لِّلَّذِيۡنَ كَفَرُوۡا ۙ لِيَسۡتَيۡقِنَ الَّذِيۡنَ اُوۡتُوا الۡكِتٰبَ وَيَزۡدَادَ الَّذِيۡنَ اٰمَنُوۡۤا اِيۡمَانًا​ وَّلَا يَرۡتَابَ الَّذِيۡنَ اُوۡتُوا الۡكِتٰبَ وَالۡمُؤۡمِنُوۡنَ​ۙ وَلِيَقُوۡلَ الَّذِيۡنَ فِىۡ قُلُوۡبِهِمۡ مَّرَضٌ وَّالۡكٰفِرُوۡنَ مَاذَاۤ اَرَادَ اللّٰهُ بِهٰذَا مَثَلًا ​ؕ كَذٰلِكَ يُضِلُّ اللّٰهُ مَنۡ يَّشَآءُ وَيَهۡدِىۡ مَنۡ يَّشَآءُ ​ؕ وَمَا يَعۡلَمُ جُنُوۡدَ رَبِّكَ اِلَّا هُوَ ​ؕ وَمَا هِىَ اِلَّا ذِكۡرٰى لِلۡبَشَرِ‏'),
('s74a32', 32, 74, 'كَلَّا وَٱلْقَمَرِ', 'كَلَّا وَالۡقَمَرِۙ‏'),
('s74a33', 33, 74, 'وَٱلَّيْلِ إِذْ أَدْبَرَ', 'وَالَّيۡلِ اِذۡ اَدۡبَرَۙ‏'),
('s74a34', 34, 74, 'وَٱلصُّبْحِ إِذَآ أَسْفَرَ', 'وَالصُّبۡحِ اِذَاۤ اَسۡفَرَۙ‏'),
('s74a35', 35, 74, 'إِنَّهَا لَإِحْدَى ٱلْكُبَرِ', 'اِنَّهَا لَاِحۡدَى الۡكُبَرِۙ‏'),
('s74a36', 36, 74, 'نَذِيرًا لِّلْبَشَرِ', 'نَذِيۡرًا لِّلۡبَشَرِۙ‏'),
('s74a37', 37, 74, 'لِمَن شَآءَ مِنكُمْ أَن يَتَقَدَّمَ أَوْ يَتَأَخَّرَ', 'لِمَنۡ شَآءَ مِنۡكُمۡ اَنۡ يَّتَقَدَّمَ اَوۡ يَتَاَخَّرَؕ‏'),
('s74a38', 38, 74, 'كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ رَهِينَةٌ', 'كُلُّ نَفۡسٍ ۢ بِمَا كَسَبَتۡ رَهِيۡنَةٌ ۙ‏'),
('s74a39', 39, 74, 'إِلَّآ أَصْحَـٰبَ ٱلْيَمِينِ', 'اِلَّاۤ اَصۡحٰبَ الۡيَمِيۡنِۛ ؕ‏'),
('s74a40', 40, 74, 'فِى جَنَّـٰتٍ يَتَسَآءَلُونَ', 'فِىۡ جَنّٰتٍ ۛ يَتَسَآءَلُوۡنَۙ‏'),
('s74a41', 41, 74, 'عَنِ ٱلْمُجْرِمِينَ', 'عَنِ الۡمُجۡرِمِيۡنَۙ‏'),
('s74a42', 42, 74, 'مَا سَلَكَكُمْ فِى سَقَرَ', 'مَا سَلَـكَكُمۡ فِىۡ سَقَرَ‏'),
('s74a43', 43, 74, 'قَالُوا۟ لَمْ نَكُ مِنَ ٱلْمُصَلِّينَ', 'قَالُوۡا لَمۡ نَكُ مِنَ الۡمُصَلِّيۡنَۙ‏'),
('s74a44', 44, 74, 'وَلَمْ نَكُ نُطْعِمُ ٱلْمِسْكِينَ', 'وَلَمۡ نَكُ نُطۡعِمُ الۡمِسۡكِيۡنَۙ‏'),
('s74a45', 45, 74, 'وَكُنَّا نَخُوضُ مَعَ ٱلْخَآئِضِينَ', 'وَكُنَّا نَخُوۡضُ مَعَ الۡخَـآٮِٕضِيۡنَۙ‏'),
('s74a46', 46, 74, 'وَكُنَّا نُكَذِّبُ بِيَوْمِ ٱلدِّينِ', 'وَ كُنَّا نُكَذِّبُ بِيَوۡمِ الدِّيۡنِۙ‏'),
('s74a47', 47, 74, 'حَتَّىٰٓ أَتَىٰنَا ٱلْيَقِينُ', 'حَتّٰٓى اَتٰٮنَا الۡيَقِيۡنُؕ‏'),
('s74a48', 48, 74, 'فَمَا تَنفَعُهُمْ شَفَـٰعَةُ ٱلشَّـٰفِعِينَ', 'فَمَا تَنۡفَعُهُمۡ شَفَاعَةُ الشّٰفِعِيۡنَؕ‏'),
('s74a49', 49, 74, 'فَمَا لَهُمْ عَنِ ٱلتَّذْكِرَةِ مُعْرِضِينَ', 'فَمَا لَهُمۡ عَنِ التَّذۡكِرَةِ مُعۡرِضِيۡنَۙ‏'),
('s74a50', 50, 74, 'كَأَنَّهُمْ حُمُرٌ مُّسْتَنفِرَةٌ', 'كَاَنَّهُمۡ حُمُرٌ مُّسۡتَنۡفِرَةٌ ۙ‏'),
('s74a51', 51, 74, 'فَرَّتْ مِن قَسْوَرَةٍۭ', 'فَرَّتۡ مِنۡ قَسۡوَرَةٍ ؕ‏'),
('s74a52', 52, 74, 'بَلْ يُرِيدُ كُلُّ ٱمْرِئٍ مِّنْهُمْ أَن يُؤْتَىٰ صُحُفًا مُّنَشَّرَةً', 'بَلۡ يُرِيۡدُ كُلُّ امۡرِىٴٍ مِّنۡهُمۡ اَنۡ يُّؤۡتٰى صُحُفًا مُّنَشَّرَةً ۙ‏ ﻿﻿'),
('s74a53', 53, 74, 'كَلَّا ۖ بَل لَّا يَخَافُونَ ٱلْـَٔاخِرَةَ', 'كَلَّا ​ؕ بَلۡ لَّا يَخَافُوۡنَ الۡاٰخِرَةَ ؕ‏'),
('s74a54', 54, 74, 'كَلَّآ إِنَّهُۥ تَذْكِرَةٌ', 'كَلَّاۤ اِنَّهٗ تَذۡكِرَةٌ​ ۚ‏'),
('s74a55', 55, 74, 'فَمَن شَآءَ ذَكَرَهُۥ', 'فَمَنۡ شَآءَ ذَكَرَهٗ ؕ‏'),
('s74a56', 56, 74, 'وَمَا يَذْكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ هُوَ أَهْلُ ٱلتَّقْوَىٰ وَأَهْلُ ٱلْمَغْفِرَةِ', 'وَمَا يَذۡكُرُوۡنَ اِلَّاۤ اَنۡ يَّشَآءَ اللّٰهُ​ ؕ هُوَ اَهۡلُ التَّقۡوٰى وَاَهۡلُ الۡمَغۡفِرَةِ‏'),
('s75a1', 1, 75, ' لَآ أُقْسِمُ بِيَوْمِ ٱلْقِيَـٰمَةِ', 'لَاۤ اُقۡسِمُ بِيَوۡمِ الۡقِيٰمَةِۙ‏'),
('s75a2', 2, 75, 'وَلَآ أُقْسِمُ بِٱلنَّفْسِ ٱللَّوَّامَةِ', 'وَلَاۤ اُقۡسِمُ بِالنَّفۡسِ اللَّوَّامَةِؕ‏'),
('s75a3', 3, 75, 'أَيَحْسَبُ ٱلْإِنسَـٰنُ أَلَّن نَّجْمَعَ عِظَامَهُۥ', 'اَيَحۡسَبُ الۡاِنۡسَانُ اَلَّنۡ نَّجۡمَعَ عِظَامَهٗؕ‏'),
('s75a4', 4, 75, 'بَلَىٰ قَـٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّىَ بَنَانَهُۥ', 'بَلٰى قٰدِرِيۡنَ عَلٰٓى اَنۡ نُّسَوِّىَ بَنَانَهٗ‏'),
('s75a5', 5, 75, 'بَلْ يُرِيدُ ٱلْإِنسَـٰنُ لِيَفْجُرَ أَمَامَهُۥ', 'بَلۡ يُرِيۡدُ الۡاِنۡسَانُ لِيَفۡجُرَ اَمَامَهٗ​ۚ‏'),
('s75a6', 6, 75, 'يَسْـَٔلُ أَيَّانَ يَوْمُ ٱلْقِيَـٰمَةِ', 'يَسۡـَٔـلُ اَيَّانَ يَوۡمُ الۡقِيٰمَةِؕ‏'),
('s75a7', 7, 75, 'فَإِذَا بَرِقَ ٱلْبَصَرُ', 'فَاِذَا بَرِقَ الۡبَصَرُۙ‏'),
('s75a8', 8, 75, 'وَخَسَفَ ٱلْقَمَرُ', 'وَخَسَفَ الۡقَمَرُۙ‏'),
('s75a9', 9, 75, 'وَجُمِعَ ٱلشَّمْسُ وَٱلْقَمَرُ', 'وَجُمِعَ الشَّمۡسُ وَالۡقَمَرُۙ‏'),
('s75a10', 10, 75, 'يَقُولُ ٱلْإِنسَـٰنُ يَوْمَئِذٍ أَيْنَ ٱلْمَفَرُّ', 'يَقُوۡلُ الۡاِنۡسَانُ يَوۡمَٮِٕذٍ اَيۡنَ الۡمَفَرُّ​ ۚ‏'),
('s75a11', 11, 75, 'كَلَّا لَا وَزَرَ', 'كَلَّا لَا وَزَرَؕ‏'),
('s75a12', 12, 75, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمُسْتَقَرُّ', 'اِلٰى رَبِّكَ يَوۡمَٮِٕذِ اۨلۡمُسۡتَقَرُّ ؕ‏'),
('s75a13', 13, 75, 'يُنَبَّؤُا۟ ٱلْإِنسَـٰنُ يَوْمَئِذٍۭ بِمَا قَدَّمَ وَأَخَّرَ', 'يُنَبَّؤُا الۡاِنۡسَانُ يَوۡمَٮِٕذٍۢ بِمَا قَدَّمَ وَاَخَّرَؕ‏'),
('s75a14', 14, 75, 'بَلِ ٱلْإِنسَـٰنُ عَلَىٰ نَفْسِهِۦ بَصِيرَةٌ', 'بَلِ الۡاِنۡسَانُ عَلٰى نَفۡسِهٖ بَصِيۡرَةٌ ۙ‏'),
('s75a15', 15, 75, 'وَلَوْ أَلْقَىٰ مَعَاذِيرَهُۥ', 'وَّلَوۡ اَلۡقٰى مَعَاذِيۡرَهٗؕ‏'),
('s75a16', 16, 75, 'لَا تُحَرِّكْ بِهِۦ لِسَانَكَ لِتَعْجَلَ بِهِۦٓ', 'لَا تُحَرِّكۡ بِهٖ لِسَانَكَ لِتَعۡجَلَ بِهٖؕ‏'),
('s75a17', 17, 75, 'إِنَّ عَلَيْنَا جَمْعَهُۥ وَقُرْءَانَهُۥ', 'اِنَّ عَلَيۡنَا جَمۡعَهٗ وَقُرۡاٰنَهٗۚ  ۖ‏'),
('s75a18', 18, 75, 'فَإِذَا قَرَأْنَـٰهُ فَٱتَّبِعْ قُرْءَانَهُۥ', 'فَاِذَا قَرَاۡنٰهُ فَاتَّبِعۡ قُرۡاٰنَهٗ​ۚ‏'),
('s75a19', 19, 75, 'ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُۥ', 'ثُمَّ اِنَّ عَلَيۡنَا بَيَانَهٗؕ‏'),
('s75a20', 20, 75, 'كَلَّا بَلْ تُحِبُّونَ ٱلْعَاجِلَةَ', 'كَلَّا بَلۡ تُحِبُّوۡنَ الۡعَاجِلَةَ ۙ‏'),
('s75a21', 21, 75, 'وَتَذَرُونَ ٱلْـَٔاخِرَةَ', 'وَتَذَرُوۡنَ الۡاٰخِرَةَ ؕ‏'),
('s75a22', 22, 75, 'وُجُوهٌ يَوْمَئِذٍ نَّاضِرَةٌ', 'وُجُوۡهٌ يَّوۡمَٮِٕذٍ نَّاضِرَةٌ ۙ‏'),
('s75a23', 23, 75, 'إِلَىٰ رَبِّهَا نَاظِرَةٌ', 'اِلٰى رَبِّهَا نَاظِرَةٌ​ ۚ‏'),
('s75a24', 24, 75, 'وَوُجُوهٌ يَوْمَئِذٍۭ بَاسِرَةٌ', 'وَوُجُوۡهٌ يَّوۡمَٮِٕذٍۢ بَاسِرَةٌ ۙ‏'),
('s75a25', 25, 75, 'تَظُنُّ أَن يُفْعَلَ بِهَا فَاقِرَةٌ', 'تَظُنُّ اَنۡ يُّفۡعَلَ بِهَا فَاقِرَةٌ ؕ‏'),
('s75a26', 26, 75, 'كَلَّآ إِذَا بَلَغَتِ ٱلتَّرَاقِىَ', 'كَلَّاۤ اِذَا بَلَغَتِ التَّرَاقِىَۙ‏'),
('s75a27', 27, 75, 'وَقِيلَ مَنْ ۜ رَاقٍ', 'وَقِيۡلَ مَنۡ رَاقٍۙ‏'),
('s75a28', 28, 75, 'وَظَنَّ أَنَّهُ ٱلْفِرَاقُ', 'وَّظَنَّ اَنَّهُ الۡفِرَاقُۙ‏'),
('s75a29', 29, 75, 'وَٱلْتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ', 'وَالۡتَفَّتِ السَّاقُ بِالسَّاقِۙ‏'),
('s75a30', 30, 75, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمَسَاقُ', 'اِلٰى رَبِّكَ يَوۡمَٮِٕذِ اۨلۡمَسَاقُؕ‏'),
('s75a31', 31, 75, 'فَلَا صَدَّقَ وَلَا صَلَّىٰ', 'فَلَا صَدَّقَ وَلَا صَلّٰىۙ‏'),
('s75a32', 32, 75, 'وَلَـٰكِن كَذَّبَ وَتَوَلَّىٰ', 'وَلٰڪِنۡ كَذَّبَ وَتَوَلّٰىۙ‏'),
('s75a33', 33, 75, 'ثُمَّ ذَهَبَ إِلَىٰٓ أَهْلِهِۦ يَتَمَطَّىٰٓ', 'ثُمَّ ذَهَبَ اِلٰٓى اَهۡلِهٖ يَتَمَطّٰىؕ‏'),
('s75a34', 34, 75, 'أَوْلَىٰ لَكَ فَأَوْلَىٰ', 'اَوۡلٰى لَكَ فَاَوۡلٰىۙ‏'),
('s75a35', 35, 75, 'ثُمَّ أَوْلَىٰ لَكَ فَأَوْلَىٰٓ', 'ثُمَّ اَوۡلٰى لَكَ فَاَوۡلٰىؕ‏'),
('s75a36', 36, 75, 'أَيَحْسَبُ ٱلْإِنسَـٰنُ أَن يُتْرَكَ سُدًى', 'اَيَحۡسَبُ الۡاِنۡسَانُ اَنۡ يُّتۡرَكَ سُدًىؕ‏'),
('s75a37', 37, 75, 'أَلَمْ يَكُ نُطْفَةً مِّن مَّنِىٍّ يُمْنَىٰ', 'اَلَمۡ يَكُ نُطۡفَةً مِّنۡ مَّنِىٍّ يُّمۡنٰىۙ‏'),
('s75a38', 38, 75, 'ثُمَّ كَانَ عَلَقَةً فَخَلَقَ فَسَوَّىٰ', 'ثُمَّ كَانَ عَلَقَةً فَخَلَقَ فَسَوّٰىۙ‏'),
('s75a39', 39, 75, 'فَجَعَلَ مِنْهُ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ', 'فَجَعَلَ مِنۡهُ الزَّوۡجَيۡنِ الذَّكَرَ وَالۡاُنۡثٰىؕ‏'),
('s75a40', 40, 75, 'أَلَيْسَ ذَٰلِكَ بِقَـٰدِرٍ عَلَىٰٓ أَن يُحْـِۧىَ ٱلْمَوْتَىٰ', 'اَلَيۡسَ ذٰلِكَ بِقٰدِرٍ عَلٰٓى اَنۡ يُّحۡـىِۦَ الۡمَوۡتٰى‏'),
('s76a1', 1, 76, ' هَلْ أَتَىٰ عَلَى ٱلْإِنسَـٰنِ حِينٌ مِّنَ ٱلدَّهْرِ لَمْ يَكُن شَيْـًٔا مَّذْكُورًا', 'هَلۡ اَتٰى عَلَى الۡاِنۡسَانِ حِيۡنٌ مِّنَ الدَّهۡرِ لَمۡ يَكُنۡ شَيۡـًٔـا مَّذۡكُوۡرًا‏'),
('s76a2', 2, 76, 'إِنَّا خَلَقْنَا ٱلْإِنسَـٰنَ مِن نُّطْفَةٍ أَمْشَاجٍ نَّبْتَلِيهِ فَجَعَلْنَـٰهُ سَمِيعًۢا بَصِيرًا', 'اِنَّا خَلَقۡنَا الۡاِنۡسَانَ مِنۡ نُّطۡفَةٍ اَمۡشَاجٍۖ نَّبۡتَلِيۡهِ فَجَعَلۡنٰهُ سَمِيۡعًۢا بَصِيۡرًا‏'),
('s76a3', 3, 76, 'إِنَّا هَدَيْنَـٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا', 'اِنَّا هَدَيۡنٰهُ السَّبِيۡلَ اِمَّا شَاكِرًا وَّاِمَّا كَفُوۡرًا‏'),
('s76a4', 4, 76, 'إِنَّآ أَعْتَدْنَا لِلْكَـٰفِرِينَ سَلَـٰسِلَا۟ وَأَغْلَـٰلًا وَسَعِيرًا', 'اِنَّاۤ اَعۡتَدۡنَا لِلۡكٰفِرِيۡنَ سَلٰسِلَا۟ وَاَغۡلٰلًا وَّسَعِيۡرًا‏'),
('s76a5', 5, 76, 'إِنَّ ٱلْأَبْرَارَ يَشْرَبُونَ مِن كَأْسٍ كَانَ مِزَاجُهَا كَافُورًا', 'اِنَّ الۡاَبۡرَارَ يَشۡرَبُوۡنَ مِنۡ كَاۡسٍ كَانَ مِزَاجُهَا كَافُوۡرًا​ۚ‏ ﻿﻿'),
('s76a6', 6, 76, 'عَيْنًا يَشْرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفْجِيرًا', 'عَيۡنًا يَّشۡرَبُ بِهَا عِبَادُ اللّٰهِ يُفَجِّرُوۡنَهَا تَفۡجِيۡرًا‏'),
('s76a7', 7, 76, 'يُوفُونَ بِٱلنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُۥ مُسْتَطِيرًا', 'يُوۡفُوۡنَ بِالنَّذۡرِ وَيَخَافُوۡنَ يَوۡمًا كَانَ شَرُّهٗ مُسۡتَطِيۡرًا‏ ﻿﻿'),
('s76a8', 8, 76, 'وَيُطْعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا', 'وَيُطۡعِمُوۡنَ الطَّعَامَ عَلٰى حُبِّهٖ مِسۡكِيۡنًا وَّيَتِيۡمًا وَّاَسِيۡرًا‏ ﻿﻿'),
('s76a9', 9, 76, 'إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ ٱللَّهِ لَا نُرِيدُ مِنكُمْ جَزَآءً وَلَا شُكُورًا', 'اِنَّمَا نُطۡعِمُكُمۡ لِـوَجۡهِ اللّٰهِ لَا نُرِيۡدُ مِنۡكُمۡ جَزَآءً وَّلَا شُكُوۡرًا‏'),
('s76a10', 10, 76, 'إِنَّا نَخَافُ مِن رَّبِّنَا يَوْمًا عَبُوسًا قَمْطَرِيرًا', 'اِنَّا نَخَافُ مِنۡ رَّبِّنَا يَوۡمًا عَبُوۡسًا قَمۡطَرِيۡرًا‏'),
('s76a11', 11, 76, 'فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلْيَوْمِ وَلَقَّىٰهُمْ نَضْرَةً وَسُرُورًا', 'فَوَقٰٮهُمُ اللّٰهُ شَرَّ ذٰلِكَ الۡيَوۡمِ وَ لَقّٰٮهُمۡ نَضۡرَةً وَّسُرُوۡرًا​ۚ‏ ﻿﻿'),
('s76a12', 12, 76, 'وَجَزَىٰهُم بِمَا صَبَرُوا۟ جَنَّةً وَحَرِيرًا', 'وَجَزٰٮهُمۡ بِمَا صَبَرُوۡا جَنَّةً وَّحَرِيۡرًا ۙ‏'),
('s76a13', 13, 76, 'مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ ۖ لَا يَرَوْنَ فِيهَا شَمْسًا وَلَا زَمْهَرِيرًا', 'مُّتَّكِـِٕـيۡنَ فِيۡهَا عَلَى الۡاَرَآٮِٕكِ​ۚ لَا يَرَوۡنَ فِيۡهَا شَمۡسًا وَّلَا زَمۡهَرِيۡرًا​ۚ‏'),
('s76a14', 14, 76, 'وَدَانِيَةً عَلَيْهِمْ ظِلَـٰلُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلًا', 'وَدَانِيَةً عَلَيۡهِمۡ ظِلٰلُهَا وَذُلِّلَتۡ قُطُوۡفُهَا تَذۡلِيۡلًا‏'),
('s76a15', 15, 76, 'وَيُطَافُ عَلَيْهِم بِـَٔانِيَةٍ مِّن فِضَّةٍ وَأَكْوَابٍ كَانَتْ قَوَارِيرَا۠', 'وَيُطَافُ عَلَيۡهِمۡ بِاٰنِيَةٍ مِّنۡ فِضَّةٍ وَّاَكۡوَابٍ كَانَتۡ قَوَارِيۡرَا۟ ۙ‏ ﻿﻿'),
('s76a16', 16, 76, 'قَوَارِيرَا۟ مِن فِضَّةٍ قَدَّرُوهَا تَقْدِيرًا', 'قَوَارِيۡرَا۟ مِنۡ فِضَّةٍ قَدَّرُوۡهَا تَقۡدِيۡرًا‏'),
('s76a17', 17, 76, 'وَيُسْقَوْنَ فِيهَا كَأْسًا كَانَ مِزَاجُهَا زَنجَبِيلًا', '​ ​ وَيُسۡقَوۡنَ فِيۡهَا كَاۡسًا كَانَ مِزَاجُهَا زَنۡجَبِيۡلًا ۚ‏'),
('s76a18', 18, 76, 'عَيْنًا فِيهَا تُسَمَّىٰ سَلْسَبِيلًا', 'عَيۡنًا فِيۡهَا تُسَمّٰى سَلۡسَبِيۡلًا‏'),
('s76a19', 19, 76, '۞ وَيَطُوفُ عَلَيْهِمْ وِلْدَٰنٌ مُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤًا مَّنثُورًا', 'وَيَطُوۡفُ عَلَيۡهِمۡ وِلۡدَانٌ مُّخَلَّدُوۡنَ​ۚ اِذَا رَاَيۡتَهُمۡ حَسِبۡتَهُمۡ لُـؤۡلُـؤًا مَّنۡثُوۡرًا‏'),
('s76a20', 20, 76, 'وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيمًا وَمُلْكًا كَبِيرًا', 'وَاِذَا رَاَيۡتَ ثَمَّ رَاَيۡتَ نَعِيۡمًا وَّمُلۡكًا كَبِيۡرًا‏'),
('s76a21', 21, 76, 'عَـٰلِيَهُمْ ثِيَابُ سُندُسٍ خُضْرٌ وَإِسْتَبْرَقٌ ۖ وَحُلُّوٓا۟ أَسَاوِرَ مِن فِضَّةٍ وَسَقَىٰهُمْ رَبُّهُمْ شَرَابًا طَهُورًا', 'عٰلِيَهُمۡ ثِيَابُ سُنۡدُسٍ خُضۡرٌ وَّاِسۡتَبۡرَقٌ​ وَّحُلُّوۡۤا اَسَاوِرَ مِنۡ فِضَّةٍ ​ۚوَسَقٰٮهُمۡ رَبُّهُمۡ شَرَابًا طَهُوۡرًا‏'),
('s76a22', 22, 76, 'إِنَّ هَـٰذَا كَانَ لَكُمْ جَزَآءً وَكَانَ سَعْيُكُم مَّشْكُورًا', 'اِنَّ هٰذَا كَانَ لَـكُمۡ جَزَآءً وَّكَانَ سَعۡيُكُمۡ مَّشۡكُوۡرًا‏'),
('s76a23', 23, 76, 'إِنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ ٱلْقُرْءَانَ تَنزِيلًا', 'اِنَّا نَحۡنُ نَزَّلۡنَا عَلَيۡكَ الۡقُرۡاٰنَ تَنۡزِيۡلًا ۚ‏'),
('s76a24', 24, 76, 'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمْ ءَاثِمًا أَوْ كَفُورًا', 'فَاصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تُطِعۡ مِنۡهُمۡ اٰثِمًا اَوۡ كَفُوۡرًا​ۚ‏ ﻿﻿'),
('s76a25', 25, 76, 'وَٱذْكُرِ ٱسْمَ رَبِّكَ بُكْرَةً وَأَصِيلًا', 'وَاذۡكُرِ اسۡمَ رَبِّكَ بُكۡرَةً وَّاَصِيۡلًا ۚ  ۖ‏'),
('s76a26', 26, 76, 'وَمِنَ ٱلَّيْلِ فَٱسْجُدْ لَهُۥ وَسَبِّحْهُ لَيْلًا طَوِيلًا', 'وَمِنَ الَّيۡلِ فَاسۡجُدۡ لَهٗ وَسَبِّحۡهُ لَيۡلًا طَوِيۡلًا‏'),
('s76a27', 27, 76, 'إِنَّ هَـٰٓؤُلَآءِ يُحِبُّونَ ٱلْعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمْ يَوْمًا ثَقِيلًا', 'اِنَّ هٰٓؤُلَاۤءِ يُحِبُّوۡنَ الۡعَاجِلَةَ وَيَذَرُوۡنَ وَرَآءَهُمۡ يَوۡمًا ثَقِيۡلًا‏'),
('s76a28', 28, 76, 'نَّحْنُ خَلَقْنَـٰهُمْ وَشَدَدْنَآ أَسْرَهُمْ ۖ وَإِذَا شِئْنَا بَدَّلْنَآ أَمْثَـٰلَهُمْ تَبْدِيلًا', 'نَحۡنُ خَلَقۡنٰهُمۡ وَشَدَدۡنَاۤ اَسۡرَهُمۡ​ۚ وَاِذَا شِئۡنَا بَدَّلۡنَاۤ اَمۡثَالَهُمۡ تَبۡدِيۡلًا‏'),
('s76a29', 29, 76, 'إِنَّ هَـٰذِهِۦ تَذْكِرَةٌ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', 'اِنَّ هٰذِهٖ تَذۡكِرَةٌ ​ۚ فَمَنۡ شَآءَ اتَّخَذَ اِلٰى رَبِّهٖ سَبِيۡلًا‏ ﻿﻿'),
('s76a30', 30, 76, 'وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', 'وَمَا تَشَآءُوۡنَ اِلَّاۤ اَنۡ يَّشَآءَ اللّٰهُ ​ؕ اِنَّ اللّٰهَ كَانَ عَلِيۡمًا حَكِيۡمًا  ۖ‏'),
('s76a31', 31, 76, 'يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ ۚ وَٱلظَّـٰلِمِينَ أَعَدَّ لَهُمْ عَذَابًا أَلِيمًۢا', 'يُّدۡخِلُ مَنۡ يَّشَآءُ فِىۡ رَحۡمَتِهٖ​ؕ وَالظّٰلِمِيۡنَ اَعَدَّ لَهُمۡ عَذَابًا اَلِيۡمًا‏'),
('s77a1', 1, 77, ' وَٱلْمُرْسَلَـٰتِ عُرْفًا', 'وَالۡمُرۡسَلٰتِ عُرۡفًا ۙ‏'),
('s77a2', 2, 77, 'فَٱلْعَـٰصِفَـٰتِ عَصْفًا', 'فَالۡعٰصِفٰتِ عَصۡفًا ۙ‏'),
('s77a3', 3, 77, 'وَٱلنَّـٰشِرَٰتِ نَشْرًا', 'وَّالنّٰشِرٰتِ نَشۡرًا ۙ‏'),
('s77a4', 4, 77, 'فَٱلْفَـٰرِقَـٰتِ فَرْقًا', 'فَالۡفٰرِقٰتِ فَرۡقًا ۙ‏'),
('s77a5', 5, 77, 'فَٱلْمُلْقِيَـٰتِ ذِكْرًا', 'فَالۡمُلۡقِيٰتِ ذِكۡرًا ۙ‏'),
('s77a6', 6, 77, 'عُذْرًا أَوْ نُذْرًا', 'عُذۡرًا اَوۡ نُذۡرًا ۙ‏'),
('s77a7', 7, 77, 'إِنَّمَا تُوعَدُونَ لَوَٰقِعٌ', 'اِنَّمَا تُوۡعَدُوۡنَ لَوَاقِعٌ ؕ‏'),
('s77a8', 8, 77, 'فَإِذَا ٱلنُّجُومُ طُمِسَتْ', 'فَاِذَا النُّجُوۡمُ طُمِسَتۡۙ‏'),
('s77a9', 9, 77, 'وَإِذَا ٱلسَّمَآءُ فُرِجَتْ', 'وَ اِذَا السَّمَآءُ فُرِجَتۡۙ‏'),
('s77a10', 10, 77, 'وَإِذَا ٱلْجِبَالُ نُسِفَتْ', 'وَاِذَا الۡجِبَالُ نُسِفَتۡۙ‏'),
('s77a11', 11, 77, 'وَإِذَا ٱلرُّسُلُ أُقِّتَتْ', 'وَاِذَا الرُّسُلُ اُقِّتَتۡؕ‏'),
('s77a12', 12, 77, 'لِأَىِّ يَوْمٍ أُجِّلَتْ', 'لِاَىِّ يَوۡمٍ اُجِّلَتۡؕ‏'),
('s77a13', 13, 77, 'لِيَوْمِ ٱلْفَصْلِ', 'لِيَوۡمِ الۡفَصۡلِ​ۚ‏'),
('s77a14', 14, 77, 'وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلْفَصْلِ', 'وَمَاۤ اَدۡرٰٮكَ مَا يَوۡمُ الۡفَصۡلِؕ‏'),
('s77a15', 15, 77, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيۡلٌ يَّوۡمَٮِٕذٍ لِّلۡمُكَذِّبِيۡنَ‏'),
('s77a16', 16, 77, 'أَلَمْ نُهْلِكِ ٱلْأَوَّلِينَ', 'اَلَمۡ نُهۡلِكِ الۡاَوَّلِيۡنَؕ‏'),
('s77a17', 17, 77, 'ثُمَّ نُتْبِعُهُمُ ٱلْـَٔاخِرِينَ', 'ثُمَّ نُتۡبِعُهُمُ الۡاٰخِرِيۡنَ‏'),
('s77a18', 18, 77, 'كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ', 'كَذٰلِكَ نَفۡعَلُ بِالۡمُجۡرِمِيۡنَ‏'),
('s77a19', 19, 77, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيۡلٌ يَّوۡمَٮِٕذٍ لِّلۡمُكَذِّبِيۡنَ‏'),
('s77a20', 20, 77, 'أَلَمْ نَخْلُقكُّم مِّن مَّآءٍ مَّهِينٍ', 'اَلَمۡ نَخۡلُقۡكُّمۡ مِّنۡ مَّآءٍ مَّهِيۡنٍۙ‏'),
('s77a21', 21, 77, 'فَجَعَلْنَـٰهُ فِى قَرَارٍ مَّكِينٍ', 'فَجَعَلۡنٰهُ فِىۡ قَرَارٍ مَّكِيۡنٍۙ‏'),
('s77a22', 22, 77, 'إِلَىٰ قَدَرٍ مَّعْلُومٍ', 'اِلٰى قَدَرٍ مَّعۡلُوۡمٍۙ‏'),
('s77a23', 23, 77, 'فَقَدَرْنَا فَنِعْمَ ٱلْقَـٰدِرُونَ', 'فَقَدَرۡنَا ۖ فَنِعۡمَ الۡقٰدِرُوۡنَ‏'),
('s77a24', 24, 77, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيۡلٌ يَّوۡمَٮِٕذٍ لِّلۡمُكَذِّبِيۡنَ‏'),
('s77a25', 25, 77, 'أَلَمْ نَجْعَلِ ٱلْأَرْضَ كِفَاتًا', 'اَلَمۡ نَجۡعَلِ الۡاَرۡضَ كِفَاتًا ۙ‏'),
('s77a26', 26, 77, 'أَحْيَآءً وَأَمْوَٰتًا', 'اَحۡيَآءً وَّاَمۡوَاتًا ۙ‏'),
('s77a27', 27, 77, 'وَجَعَلْنَا فِيهَا رَوَٰسِىَ شَـٰمِخَـٰتٍ وَأَسْقَيْنَـٰكُم مَّآءً فُرَاتًا', 'وَّجَعَلۡنَا فِيۡهَا رَوَاسِىَ شٰمِخٰتٍ وَّ اَسۡقَيۡنٰكُمۡ مَّآءً فُرَاتًا ؕ‏'),
('s77a28', 28, 77, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيۡلٌ يَّوۡمَٮِٕذٍ لِّلۡمُكَذِّبِيۡنَ‏'),
('s77a29', 29, 77, 'ٱنطَلِقُوٓا۟ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ', 'اِنْطَلِقُوۡۤا اِلٰى مَا كُنۡتُمۡ بِهٖ تُكَذِّبُوۡنَ​ۚ‏'),
('s77a30', 30, 77, 'ٱنطَلِقُوٓا۟ إِلَىٰ ظِلٍّ ذِى ثَلَـٰثِ شُعَبٍ', 'اِنْطَلِقُوۡۤا اِلٰى ظِلٍّ ذِىۡ ثَلٰثِ شُعَبٍۙ‏'),
('s77a31', 31, 77, 'لَّا ظَلِيلٍ وَلَا يُغْنِى مِنَ ٱللَّهَبِ', 'لَّا ظَلِيۡلٍ وَّلَا يُغۡنِىۡ مِنَ اللَّهَبِؕ‏'),
('s77a32', 32, 77, 'إِنَّهَا تَرْمِى بِشَرَرٍ كَٱلْقَصْرِ', 'اِنَّهَا تَرۡمِىۡ بِشَرَرٍ كَالۡقَصۡرِ​ۚ‏'),
('s77a33', 33, 77, 'كَأَنَّهُۥ جِمَـٰلَتٌ صُفْرٌ', 'كَاَنَّهٗ جِمٰلَتٌ صُفۡرٌ ؕ‏'),
('s77a34', 34, 77, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيۡلٌ يَّوۡمَٮِٕذٍ لِّلۡمُكَذِّبِيۡنَ‏'),
('s77a35', 35, 77, 'هَـٰذَا يَوْمُ لَا يَنطِقُونَ', 'هٰذَا يَوۡمُ لَا يَنۡطِقُوۡنَۙ‏'),
('s77a36', 36, 77, 'وَلَا يُؤْذَنُ لَهُمْ فَيَعْتَذِرُونَ', 'وَلَا يُؤۡذَنُ لَهُمۡ فَيَـعۡتَذِرُوۡنَ‏'),
('s77a37', 37, 77, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيۡلٌ يَّوۡمَٮِٕذٍ لِّلۡمُكَذِّبِيۡنَ‏'),
('s77a38', 38, 77, 'هَـٰذَا يَوْمُ ٱلْفَصْلِ ۖ جَمَعْنَـٰكُمْ وَٱلْأَوَّلِينَ', 'هٰذَا يَوۡمُ الۡفَصۡلِ​ۚ جَمَعۡنٰكُمۡ وَالۡاَوَّلِيۡنَ‏'),
('s77a39', 39, 77, 'فَإِن كَانَ لَكُمْ كَيْدٌ فَكِيدُونِ', 'فَاِنۡ كَانَ لَـكُمۡ كَيۡدٌ فَكِيۡدُوۡنِ‏'),
('s77a40', 40, 77, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيۡلٌ يَّوۡمَٮِٕذٍ لِّلۡمُكَذِّبِيۡنَ‏'),
('s77a41', 41, 77, 'إِنَّ ٱلْمُتَّقِينَ فِى ظِلَـٰلٍ وَعُيُونٍ', 'اِنَّ الۡمُتَّقِيۡنَ فِىۡ ظِلٰلٍ وَّعُيُوۡنٍۙ‏'),
('s77a42', 42, 77, 'وَفَوَٰكِهَ مِمَّا يَشْتَهُونَ', 'وَّفَوَاكِهَ مِمَّا يَشۡتَهُوۡنَؕ‏'),
('s77a43', 43, 77, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَا كُنتُمْ تَعْمَلُونَ', 'كُلُوۡا وَاشۡرَبُوۡا هَنِيْٓئًا ۢ بِمَا كُنۡتُمۡ تَعۡمَلُوۡنَ‏'),
('s77a44', 44, 77, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'اِنَّا كَذٰلِكَ نَجۡزِى الۡمُحۡسِنِيۡنَ‏'),
('s77a45', 45, 77, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيۡلٌ يَّوۡمَٮِٕذٍ لِّلۡمُكَذِّبِيۡنَ‏'),
('s77a46', 46, 77, 'كُلُوا۟ وَتَمَتَّعُوا۟ قَلِيلًا إِنَّكُم مُّجْرِمُونَ', 'كُلُوۡا وَتَمَتَّعُوۡا قَلِيۡلًا اِنَّكُمۡ مُّجۡرِمُوۡنَ‏'),
('s77a47', 47, 77, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيۡلٌ يَّوۡمَٮِٕذٍ لِّلۡمُكَذِّبِيۡنَ‏'),
('s77a48', 48, 77, 'وَإِذَا قِيلَ لَهُمُ ٱرْكَعُوا۟ لَا يَرْكَعُونَ', 'وَاِذَا قِيۡلَ لَهُمُ ارۡكَعُوۡا لَا يَرۡكَعُوۡنَ‏'),
('s77a49', 49, 77, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيۡلٌ يَّوۡمَٮِٕذٍ لِّلۡمُكَذِّبِيۡنَ‏'),
('s77a50', 50, 77, 'فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ', 'فَبِاَىِّ حَدِيۡثٍۢ بَعۡدَهٗ يُؤۡمِنُوۡنَ‏'),
('s78a1', 1, 78, ' عَمَّ يَتَسَآءَلُونَ', 'عَمَّ يَتَسَآءَلُوۡنَ​ۚ‏'),
('s78a2', 2, 78, 'عَنِ ٱلنَّبَإِ ٱلْعَظِيمِ', 'عَنِ النَّبَاِ الۡعَظِيۡمِۙ‏'),
('s78a3', 3, 78, 'ٱلَّذِى هُمْ فِيهِ مُخْتَلِفُونَ', 'الَّذِىۡ هُمۡ فِيۡهِ مُخۡتَلِفُوۡنَؕ‏'),
('s78a4', 4, 78, 'كَلَّا سَيَعْلَمُونَ', 'كَلَّا سَيَعۡلَمُوۡنَۙ‏'),
('s78a5', 5, 78, 'ثُمَّ كَلَّا سَيَعْلَمُونَ', 'ثُمَّ كَلَّا سَيَعۡلَمُوۡنَ‏'),
('s78a6', 6, 78, 'أَلَمْ نَجْعَلِ ٱلْأَرْضَ مِهَـٰدًا', 'اَلَمۡ نَجۡعَلِ الۡاَرۡضَ مِهٰدًا ۙ‏'),
('s78a7', 7, 78, 'وَٱلْجِبَالَ أَوْتَادًا', 'وَّالۡجِبَالَ اَوۡتَادًا ۙ‏'),
('s78a8', 8, 78, 'وَخَلَقْنَـٰكُمْ أَزْوَٰجًا', 'وَّخَلَقۡنٰكُمۡ اَزۡوَاجًا ۙ‏'),
('s78a9', 9, 78, 'وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا', 'وَّجَعَلۡنَا نَوۡمَكُمۡ سُبَاتًا ۙ‏'),
('s78a10', 10, 78, 'وَجَعَلْنَا ٱلَّيْلَ لِبَاسًا', 'وَّجَعَلۡنَا الَّيۡلَ لِبَاسًا ۙ‏'),
('s78a11', 11, 78, 'وَجَعَلْنَا ٱلنَّهَارَ مَعَاشًا', 'وَّجَعَلۡنَا النَّهَارَ مَعَاشًا‏'),
('s78a12', 12, 78, 'وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا', 'وَّبَنَيۡنَا فَوۡقَكُمۡ سَبۡعًا شِدَادًا ۙ‏'),
('s78a13', 13, 78, 'وَجَعَلْنَا سِرَاجًا وَهَّاجًا', 'وَّ جَعَلۡنَا سِرَاجًا وَّهَّاجًا ۙ‏'),
('s78a14', 14, 78, 'وَأَنزَلْنَا مِنَ ٱلْمُعْصِرَٰتِ مَآءً ثَجَّاجًا', 'وَّاَنۡزَلۡنَا مِنَ الۡمُعۡصِرٰتِ مَآءً ثَجَّاجًا ۙ‏'),
('s78a15', 15, 78, 'لِّنُخْرِجَ بِهِۦ حَبًّا وَنَبَاتًا', 'لِّـنُخۡرِجَ بِهٖ حَبًّا وَّنَبَاتًا ۙ‏'),
('s78a16', 16, 78, 'وَجَنَّـٰتٍ أَلْفَافًا', 'وَّجَنّٰتٍ اَلۡفَافًا ؕ‏'),
('s78a17', 17, 78, 'إِنَّ يَوْمَ ٱلْفَصْلِ كَانَ مِيقَـٰتًا', 'اِنَّ يَوۡمَ الۡفَصۡلِ كَانَ مِيۡقَاتًا ۙ‏'),
('s78a18', 18, 78, 'يَوْمَ يُنفَخُ فِى ٱلصُّورِ فَتَأْتُونَ أَفْوَاجًا', 'يَّوۡمَ يُنۡفَخُ فِى الصُّوۡرِ فَتَاۡتُوۡنَ اَفۡوَاجًا ۙ‏'),
('s78a19', 19, 78, 'وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتْ أَبْوَٰبًا', 'وَّفُتِحَتِ السَّمَآءُ فَكَانَتۡ اَبۡوَابًا ۙ‏'),
('s78a20', 20, 78, 'وَسُيِّرَتِ ٱلْجِبَالُ فَكَانَتْ سَرَابًا', 'وَّ سُيِّرَتِ الۡجِبَالُ فَكَانَتۡ سَرَابًا ؕ‏'),
('s78a21', 21, 78, 'إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا', 'اِنَّ جَهَنَّمَ كَانَتۡ مِرۡصَادًا ۙ‏'),
('s78a22', 22, 78, 'لِّلطَّـٰغِينَ مَـَٔابًا', 'لِّلطّٰغِيۡنَ مَاٰبًا ۙ‏'),
('s78a23', 23, 78, 'لَّـٰبِثِينَ فِيهَآ أَحْقَابًا', 'لّٰبِثِيۡنَ فِيۡهَاۤ اَحۡقَابًا​ ۚ‏'),
('s78a24', 24, 78, 'لَّا يَذُوقُونَ فِيهَا بَرْدًا وَلَا شَرَابًا', 'لَا يَذُوۡقُوۡنَ فِيۡهَا بَرۡدًا وَّلَا شَرَابًا ۙ‏'),
('s78a25', 25, 78, 'إِلَّا حَمِيمًا وَغَسَّاقًا', 'اِلَّا حَمِيۡمًا وَّغَسَّاقًا ۙ‏'),
('s78a26', 26, 78, 'جَزَآءً وِفَاقًا', 'جَزَآءً وِّفَاقًا ؕ‏'),
('s78a27', 27, 78, 'إِنَّهُمْ كَانُوا۟ لَا يَرْجُونَ حِسَابًا', 'اِنَّهُمۡ كَانُوۡا لَا يَرۡجُوۡنَ حِسَابًا ۙ‏'),
('s78a28', 28, 78, 'وَكَذَّبُوا۟ بِـَٔايَـٰتِنَا كِذَّابًا', 'وَّكَذَّبُوۡا بِاٰيٰتِنَا كِذَّابًا ؕ‏'),
('s78a29', 29, 78, 'وَكُلَّ شَىْءٍ أَحْصَيْنَـٰهُ كِتَـٰبًا', 'وَكُلَّ شَىۡءٍ اَحۡصَيۡنٰهُ كِتٰبًا ۙ‏'),
('s78a30', 30, 78, 'فَذُوقُوا۟ فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا', 'فَذُوۡقُوۡا فَلَنۡ نَّزِيۡدَكُمۡ اِلَّا عَذَابًا‏'),
('s78a31', 31, 78, 'إِنَّ لِلْمُتَّقِينَ مَفَازًا', 'اِنَّ لِلۡمُتَّقِيۡنَ مَفَازًا ۙ‏'),
('s78a32', 32, 78, 'حَدَآئِقَ وَأَعْنَـٰبًا', 'حَدَآٮِٕقَ وَاَعۡنَابًا ۙ‏'),
('s78a33', 33, 78, 'وَكَوَاعِبَ أَتْرَابًا', 'وَّكَوَاعِبَ اَتۡرَابًا ۙ‏'),
('s78a34', 34, 78, 'وَكَأْسًا دِهَاقًا', 'وَّكَاۡسًا دِهَاقًا ؕ‏'),
('s78a35', 35, 78, 'لَّا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا كِذَّٰبًا', 'لَا يَسۡمَعُوۡنَ فِيۡهَا لَـغۡوًا وَّلَا كِذّٰبًا​ ۚ‏'),
('s78a36', 36, 78, 'جَزَآءً مِّن رَّبِّكَ عَطَآءً حِسَابًا', 'جَزَآءً مِّنۡ رَّبِّكَ عَطَآءً حِسَابًا ۙ‏'),
('s78a37', 37, 78, 'رَّبِّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلرَّحْمَـٰنِ ۖ لَا يَمْلِكُونَ مِنْهُ خِطَابًا', 'رَّبِّ السَّمٰوٰتِ وَالۡاَرۡضِ وَمَا بَيۡنَهُمَا الرَّحۡمٰنِ​ لَا يَمۡلِكُوۡنَ مِنۡهُ خِطَابًا​ ۚ‏'),
('s78a38', 38, 78, 'يَوْمَ يَقُومُ ٱلرُّوحُ وَٱلْمَلَـٰٓئِكَةُ صَفًّا ۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَـٰنُ وَقَالَ صَوَابًا', 'يَوۡمَ يَقُوۡمُ الرُّوۡحُ وَالۡمَلٰٓٮِٕكَةُ صَفًّا ؕۙ لَّا يَتَكَلَّمُوۡنَ اِلَّا مَنۡ اَذِنَ لَهُ الرَّحۡمٰنُ وَقَالَ صَوَابًا​‏'),
('s78a39', 39, 78, 'ذَٰلِكَ ٱلْيَوْمُ ٱلْحَقُّ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا', 'ذٰلِكَ الۡيَوۡمُ الۡحَـقُّ​ ۚ فَمَنۡ شَآءَ اتَّخَذَ اِلٰى رَبِّهٖ مَاٰبًا‏ ﻿﻿'),
('s78a40', 40, 78, 'إِنَّآ أَنذَرْنَـٰكُمْ عَذَابًا قَرِيبًا يَوْمَ يَنظُرُ ٱلْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ ٱلْكَافِرُ يَـٰلَيْتَنِى كُنتُ تُرَٰبًۢا', 'اِنَّاۤ اَنۡذَرۡنٰـكُمۡ عَذَابًا قَرِيۡبًا ۖۚ  يَّوۡمَ يَنۡظُرُ الۡمَرۡءُ مَا قَدَّمَتۡ يَدٰهُ وَيَقُوۡلُ الۡـكٰفِرُ يٰلَيۡتَنِىۡ كُنۡتُ تُرٰبًا‏'),
('s79a1', 1, 79, ' وَٱلنَّـٰزِعَـٰتِ غَرْقًا', 'وَالنّٰزِعٰتِ غَرۡقًا ۙ‏'),
('s79a2', 2, 79, 'وَٱلنَّـٰشِطَـٰتِ نَشْطًا', 'وَّالنّٰشِطٰتِ نَشۡطًا ۙ‏'),
('s79a3', 3, 79, 'وَٱلسَّـٰبِحَـٰتِ سَبْحًا', 'وَّالسّٰبِحٰتِ سَبۡحًا ۙ‏'),
('s79a4', 4, 79, 'فَٱلسَّـٰبِقَـٰتِ سَبْقًا', 'فَالسّٰبِقٰتِ سَبۡقًا ۙ‏'),
('s79a5', 5, 79, 'فَٱلْمُدَبِّرَٰتِ أَمْرًا', 'فَالۡمُدَبِّرٰتِ اَمۡرًا​ ۘ‏'),
('s79a6', 6, 79, 'يَوْمَ تَرْجُفُ ٱلرَّاجِفَةُ', 'يَوۡمَ تَرۡجُفُ الرَّاجِفَةُ ۙ‏'),
('s79a7', 7, 79, 'تَتْبَعُهَا ٱلرَّادِفَةُ', 'تَتۡبَعُهَا الرَّادِفَةُ ؕ‏'),
('s79a8', 8, 79, 'قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ', 'قُلُوۡبٌ يَّوۡمَٮِٕذٍ وَّاجِفَةٌ ۙ‏'),
('s79a9', 9, 79, 'أَبْصَـٰرُهَا خَـٰشِعَةٌ', 'اَبۡصَارُهَا خَاشِعَةٌ​ ۘ‏'),
('s79a10', 10, 79, 'يَقُولُونَ أَءِنَّا لَمَرْدُودُونَ فِى ٱلْحَافِرَةِ', 'يَقُوۡلُوۡنَ ءَاِنَّا لَمَرۡدُوۡدُوۡنَ فِى الۡحَـافِرَةِ ؕ‏'),
('s79a11', 11, 79, 'أَءِذَا كُنَّا عِظَـٰمًا نَّخِرَةً', 'ءَاِذَا كُنَّا عِظَامًا نَّخِرَةً ؕ‏'),
('s79a12', 12, 79, 'قَالُوا۟ تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ', 'قَالُوۡا تِلۡكَ اِذًا كَرَّةٌ خَاسِرَةٌ​ ۘ‏'),
('s79a13', 13, 79, 'فَإِنَّمَا هِىَ زَجْرَةٌ وَٰحِدَةٌ', 'فَاِنَّمَا هِىَ زَجۡرَةٌ وَّاحِدَةٌ ۙ‏'),
('s79a14', 14, 79, 'فَإِذَا هُم بِٱلسَّاهِرَةِ', 'فَاِذَا هُمۡ بِالسَّاهِرَةِ ؕ‏'),
('s79a15', 15, 79, 'هَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ', 'هَلۡ اَتٰٮكَ حَدِيۡثُ مُوۡسٰى​ۘ‏'),
('s79a16', 16, 79, 'إِذْ نَادَىٰهُ رَبُّهُۥ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى', 'اِذۡ نَادٰٮهُ رَبُّهٗ بِالۡوَادِ الۡمُقَدَّسِ طُوًى​ۚ‏'),
('s79a17', 17, 79, 'ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', 'اِذۡهَبۡ اِلٰى فِرۡعَوۡنَ اِنَّهٗ طَغٰى ۖ‏'),
('s79a18', 18, 79, 'فَقُلْ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ', 'فَقُلۡ هَلۡ لَّكَ اِلٰٓى اَنۡ تَزَكّٰى ۙ‏'),
('s79a19', 19, 79, 'وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ', 'وَاَهۡدِيَكَ اِلٰى رَبِّكَ فَتَخۡشٰى​ۚ‏'),
('s79a20', 20, 79, 'فَأَرَىٰهُ ٱلْـَٔايَةَ ٱلْكُبْرَىٰ', 'فَاَرٰٮهُ الۡاٰيَةَ الۡكُبۡرٰى ۖ‏'),
('s79a21', 21, 79, 'فَكَذَّبَ وَعَصَىٰ', 'فَكَذَّبَ وَعَصٰى ۖ‏'),
('s79a22', 22, 79, 'ثُمَّ أَدْبَرَ يَسْعَىٰ', 'ثُمَّ اَدۡبَرَ يَسۡعٰىۖ‏'),
('s79a23', 23, 79, 'فَحَشَرَ فَنَادَىٰ', 'فَحَشَرَ فَنَادٰىۖ‏'),
('s79a24', 24, 79, 'فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ', 'فَقَالَ اَنَا رَبُّكُمُ الۡاَعۡلٰى ۖ‏'),
('s79a25', 25, 79, 'فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلْـَٔاخِرَةِ وَٱلْأُولَىٰٓ', 'فَاَخَذَهُ اللّٰهُ نَڪَالَ الۡاٰخِرَةِ وَالۡاُوۡلٰى ؕ‏'),
('s79a26', 26, 79, 'إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّمَن يَخْشَىٰٓ', 'اِنَّ فِىۡ ذٰلِكَ لَعِبۡرَةً لِّمَنۡ يَّخۡشٰىؕ‏'),
('s79a27', 27, 79, 'ءَأَنتُمْ أَشَدُّ خَلْقًا أَمِ ٱلسَّمَآءُ ۚ بَنَىٰهَا', 'ءَاَنۡتُمۡ اَشَدُّ خَلۡقًا اَمِ السَّمَآءُ​ ؕ بَنٰٮهَا‏'),
('s79a28', 28, 79, 'رَفَعَ سَمْكَهَا فَسَوَّىٰهَا', 'رَفَعَ سَمۡكَهَا فَسَوَّٮهَا ۙ‏'),
('s79a29', 29, 79, 'وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَىٰهَا', 'وَ اَغۡطَشَ لَيۡلَهَا وَاَخۡرَجَ ضُحٰٮهَا‏'),
('s79a30', 30, 79, 'وَٱلْأَرْضَ بَعْدَ ذَٰلِكَ دَحَىٰهَآ', 'وَالۡاَرۡضَ بَعۡدَ ذٰلِكَ دَحٰٮهَا ؕ‏'),
('s79a31', 31, 79, 'أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَىٰهَا', 'اَخۡرَجَ مِنۡهَا مَآءَهَا وَمَرۡعٰٮهَا‏'),
('s79a32', 32, 79, 'وَٱلْجِبَالَ أَرْسَىٰهَا', 'وَالۡجِبَالَ اَرۡسٰٮهَا ۙ‏'),
('s79a33', 33, 79, 'مَتَـٰعًا لَّكُمْ وَلِأَنْعَـٰمِكُمْ', 'مَتَاعًا لَّـكُمۡ وَلِاَنۡعَامِكُمۡؕ‏'),
('s79a34', 34, 79, 'فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلْكُبْرَىٰ', 'فَاِذَا جَآءَتِ الطَّآمَّةُ الۡكُبۡرٰى ۖ‏'),
('s79a35', 35, 79, 'يَوْمَ يَتَذَكَّرُ ٱلْإِنسَـٰنُ مَا سَعَىٰ', 'يَوۡمَ يَتَذَكَّرُ الۡاِنۡسَانُ مَا سَعٰىۙ‏'),
('s79a36', 36, 79, 'وَبُرِّزَتِ ٱلْجَحِيمُ لِمَن يَرَىٰ', 'وَبُرِّزَتِ الۡجَحِيۡمُ لِمَنۡ يَّرٰى‏'),
('s79a37', 37, 79, 'فَأَمَّا مَن طَغَىٰ', 'فَاَمَّا مَنۡ طَغٰىۙ‏'),
('s79a38', 38, 79, 'وَءَاثَرَ ٱلْحَيَوٰةَ ٱلدُّنْيَا', 'وَاٰثَرَ الۡحَيٰوةَ الدُّنۡيَا ۙ‏'),
('s79a39', 39, 79, 'فَإِنَّ ٱلْجَحِيمَ هِىَ ٱلْمَأْوَىٰ', 'فَاِنَّ الۡجَحِيۡمَ هِىَ الۡمَاۡوٰىؕ‏'),
('s79a40', 40, 79, 'وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ', 'وَاَمَّا مَنۡ خَافَ مَقَامَ رَبِّهٖ وَ نَهَى النَّفۡسَ عَنِ الۡهَوٰىۙ‏'),
('s79a41', 41, 79, 'فَإِنَّ ٱلْجَنَّةَ هِىَ ٱلْمَأْوَىٰ', 'فَاِنَّ الۡجَـنَّةَ هِىَ الۡمَاۡوٰىؕ‏'),
('s79a42', 42, 79, 'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا', 'يَسۡـــَٔلُوۡنَكَ عَنِ السَّاعَةِ اَيَّانَ مُرۡسٰٮهَا ؕ‏'),
('s79a43', 43, 79, 'فِيمَ أَنتَ مِن ذِكْرَىٰهَآ', 'فِيۡمَ اَنۡتَ مِنۡ ذِكۡرٰٮهَاؕ‏'),
('s79a44', 44, 79, 'إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ', 'اِلٰى رَبِّكَ مُنۡتَهٰٮهَاؕ‏'),
('s79a45', 45, 79, 'إِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَىٰهَا', 'اِنَّمَاۤ اَنۡتَ مُنۡذِرُ مَنۡ يَّخۡشٰٮهَاؕ‏'),
('s79a46', 46, 79, 'كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓا۟ إِلَّا عَشِيَّةً أَوْ ضُحَىٰهَا', 'كَاَنَّهُمۡ يَوۡمَ يَرَوۡنَهَا لَمۡ يَلۡبَثُوۡۤا اِلَّا عَشِيَّةً اَوۡ ضُحٰٮهَا‏ ﻿﻿'),
('s80a1', 1, 80, ' عَبَسَ وَتَوَلَّىٰٓ', 'عَبَسَ وَتَوَلّٰٓىۙ‏'),
('s80a2', 2, 80, 'أَن جَآءَهُ ٱلْأَعْمَىٰ', 'اَنۡ جَآءَهُ الۡاَعۡمٰىؕ‏'),
('s80a3', 3, 80, 'وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ', 'وَمَا يُدۡرِيۡكَ لَعَلَّهٗ يَزَّكّٰٓىۙ‏'),
('s80a4', 4, 80, 'أَوْ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكْرَىٰٓ', 'اَوۡ يَذَّكَّرُ فَتَنۡفَعَهُ الذِّكۡرٰىؕ‏'),
('s80a5', 5, 80, 'أَمَّا مَنِ ٱسْتَغْنَىٰ', 'اَمَّا مَنِ اسۡتَغۡنٰىۙ‏'),
('s80a6', 6, 80, 'فَأَنتَ لَهُۥ تَصَدَّىٰ', 'فَاَنۡتَ لَهٗ تَصَدّٰىؕ‏'),
('s80a7', 7, 80, 'وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ', 'وَمَا عَلَيۡكَ اَلَّا يَزَّكّٰٓىؕ‏'),
('s80a8', 8, 80, 'وَأَمَّا مَن جَآءَكَ يَسْعَىٰ', 'وَاَمَّا مَنۡ جَآءَكَ يَسۡعٰىۙ‏'),
('s80a9', 9, 80, 'وَهُوَ يَخْشَىٰ', 'وَهُوَ يَخۡشٰىۙ‏'),
('s80a10', 10, 80, 'فَأَنتَ عَنْهُ تَلَهَّىٰ', 'فَاَنۡتَ عَنۡهُ تَلَهّٰى​ۚ‏'),
('s80a11', 11, 80, 'كَلَّآ إِنَّهَا تَذْكِرَةٌ', 'كَلَّاۤ اِنَّهَا تَذۡكِرَةٌ ۚ‏'),
('s80a12', 12, 80, 'فَمَن شَآءَ ذَكَرَهُۥ', 'فَمَنۡ شَآءَ ذَكَرَهٗ​ۘ‏'),
('s80a13', 13, 80, 'فِى صُحُفٍ مُّكَرَّمَةٍ', 'فِىۡ صُحُفٍ مُّكَرَّمَةٍۙ‏'),
('s80a14', 14, 80, 'مَّرْفُوعَةٍ مُّطَهَّرَةٍۭ', 'مَّرۡفُوۡعَةٍ مُّطَهَّرَةٍ ۭۙ‏'),
('s80a15', 15, 80, 'بِأَيْدِى سَفَرَةٍ', 'بِاَيۡدِىۡ سَفَرَةٍۙ‏'),
('s80a16', 16, 80, 'كِرَامٍۭ بَرَرَةٍ', 'كِرَامٍۢ بَرَرَةٍؕ‏'),
('s80a17', 17, 80, 'قُتِلَ ٱلْإِنسَـٰنُ مَآ أَكْفَرَهُۥ', 'قُتِلَ الۡاِنۡسَانُ مَاۤ اَكۡفَرَهٗؕ‏'),
('s80a18', 18, 80, 'مِنْ أَىِّ شَىْءٍ خَلَقَهُۥ', 'مِنۡ اَىِّ شَىۡءٍ خَلَقَهٗؕ‏'),
('s80a19', 19, 80, 'مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ', 'مِنۡ نُّطۡفَةٍؕ خَلَقَهٗ فَقَدَّرَهٗ ۙ‏'),
('s80a20', 20, 80, 'ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ', 'ثُمَّ السَّبِيۡلَ يَسَّرَهٗۙ‏'),
('s80a21', 21, 80, 'ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ', 'ثُمَّ اَمَاتَهٗ فَاَقۡبَرَهٗۙ‏'),
('s80a22', 22, 80, 'ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ', 'ثُمَّ اِذَا شَآءَ اَنۡشَرَهٗؕ‏'),
('s80a23', 23, 80, 'كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ', 'كَلَّا لَـمَّا يَقۡضِ مَاۤ اَمَرَهٗؕ‏'),
('s80a24', 24, 80, 'فَلْيَنظُرِ ٱلْإِنسَـٰنُ إِلَىٰ طَعَامِهِۦٓ', 'فَلۡيَنۡظُرِ الۡاِنۡسَانُ اِلٰى طَعَامِهٖۤۙ‏'),
('s80a25', 25, 80, 'أَنَّا صَبَبْنَا ٱلْمَآءَ صَبًّا', 'اَنَّا صَبَبۡنَا الۡمَآءَ صَبًّا ۙ‏'),
('s80a26', 26, 80, 'ثُمَّ شَقَقْنَا ٱلْأَرْضَ شَقًّا', 'ثُمَّ شَقَقۡنَا الۡاَرۡضَ شَقًّا ۙ‏'),
('s80a27', 27, 80, 'فَأَنۢبَتْنَا فِيهَا حَبًّا', 'فَاَنۡۢبَتۡنَا فِيۡهَا حَبًّا ۙ‏'),
('s80a28', 28, 80, 'وَعِنَبًا وَقَضْبًا', 'وَّ عِنَبًا وَّقَضۡبًا ۙ‏'),
('s80a29', 29, 80, 'وَزَيْتُونًا وَنَخْلًا', 'وَّزَيۡتُوۡنًا وَّنَخۡلًا ؕ‏'),
('s80a30', 30, 80, 'وَحَدَآئِقَ غُلْبًا', 'وَحَدَآٮِٕقَ غُلۡبًا ۙ‏'),
('s80a31', 31, 80, 'وَفَـٰكِهَةً وَأَبًّا', 'وَّفَاكِهَةً وَّاَبًّا ۙ‏'),
('s80a32', 32, 80, 'مَّتَـٰعًا لَّكُمْ وَلِأَنْعَـٰمِكُمْ', 'مَّتَاعًا لَّـكُمۡ وَلِاَنۡعَامِكُمۡؕ‏'),
('s80a33', 33, 80, 'فَإِذَا جَآءَتِ ٱلصَّآخَّةُ', 'فَاِذَا جَآءَتِ الصَّآخَّةُ‏'),
('s80a34', 34, 80, 'يَوْمَ يَفِرُّ ٱلْمَرْءُ مِنْ أَخِيهِ', 'يَوۡمَ يَفِرُّ الۡمَرۡءُ مِنۡ اَخِيۡهِۙ‏'),
('s80a35', 35, 80, 'وَأُمِّهِۦ وَأَبِيهِ', 'وَاُمِّهٖ وَاَبِيۡهِۙ‏'),
('s80a36', 36, 80, 'وَصَـٰحِبَتِهِۦ وَبَنِيهِ', 'وَصَاحِبَتِهٖ وَبَنِيۡهِؕ‏'),
('s80a37', 37, 80, 'لِكُلِّ ٱمْرِئٍ مِّنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ', 'لِكُلِّ امۡرِیءٍ مِّنۡهُمۡ يَوۡمَٮِٕذٍ شَاۡنٌ يُّغۡنِيۡهِؕ‏'),
('s80a38', 38, 80, 'وُجُوهٌ يَوْمَئِذٍ مُّسْفِرَةٌ', 'وُجُوۡهٌ يَّوۡمَٮِٕذٍ مُّسۡفِرَةٌ ۙ‏'),
('s80a39', 39, 80, 'ضَاحِكَةٌ مُّسْتَبْشِرَةٌ', 'ضَاحِكَةٌ مُّسۡتَبۡشِرَةٌ ۚ‏'),
('s80a40', 40, 80, 'وَوُجُوهٌ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌ', 'وَوُجُوۡهٌ يَّوۡمَٮِٕذٍ عَلَيۡهَا غَبَرَةٌ ۙ‏'),
('s80a41', 41, 80, 'تَرْهَقُهَا قَتَرَةٌ', 'تَرۡهَقُهَا قَتَرَةٌ ؕ‏'),
('s80a42', 42, 80, 'أُو۟لَـٰٓئِكَ هُمُ ٱلْكَفَرَةُ ٱلْفَجَرَةُ', 'اُولٰٓٮِٕكَ هُمُ الۡكَفَرَةُ الۡفَجَرَةُ‏'),
('s81a1', 1, 81, ' إِذَا ٱلشَّمْسُ كُوِّرَتْ', 'اِذَا الشَّمۡسُ كُوِّرَتۡۙ‏'),
('s81a2', 2, 81, 'وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتْ', 'وَاِذَا النُّجُوۡمُ انْكَدَرَتۡۙ‏'),
('s81a3', 3, 81, 'وَإِذَا ٱلْجِبَالُ سُيِّرَتْ', 'وَاِذَا الۡجِبَالُ سُيِّرَتۡۙ‏'),
('s81a4', 4, 81, 'وَإِذَا ٱلْعِشَارُ عُطِّلَتْ', 'وَاِذَا الۡعِشَارُ عُطِّلَتۡۙ‏'),
('s81a5', 5, 81, 'وَإِذَا ٱلْوُحُوشُ حُشِرَتْ', 'وَاِذَا الۡوُحُوۡشُ حُشِرَتۡۙ‏'),
('s81a6', 6, 81, 'وَإِذَا ٱلْبِحَارُ سُجِّرَتْ', 'وَاِذَا الۡبِحَارُ سُجِّرَتۡۙ‏'),
('s81a7', 7, 81, 'وَإِذَا ٱلنُّفُوسُ زُوِّجَتْ', 'وَاِذَا النُّفُوۡسُ زُوِّجَتۡۙ‏'),
('s81a8', 8, 81, 'وَإِذَا ٱلْمَوْءُۥدَةُ سُئِلَتْ', 'وَاِذَا الۡمَوۡءٗدَةُ سُٮِٕلَتۡۙ‏'),
('s81a9', 9, 81, 'بِأَىِّ ذَنۢبٍ قُتِلَتْ', 'بِاَىِّ ذَنۡۢبٍ قُتِلَتۡ​ۚ‏'),
('s81a10', 10, 81, 'وَإِذَا ٱلصُّحُفُ نُشِرَتْ', 'وَاِذَا الصُّحُفُ نُشِرَتۡۙ‏'),
('s81a11', 11, 81, 'وَإِذَا ٱلسَّمَآءُ كُشِطَتْ', 'وَاِذَا السَّمَآءُ كُشِطَتۡۙ‏'),
('s81a12', 12, 81, 'وَإِذَا ٱلْجَحِيمُ سُعِّرَتْ', 'وَاِذَا الۡجَحِيۡمُ سُعِّرَتۡۙ‏'),
('s81a13', 13, 81, 'وَإِذَا ٱلْجَنَّةُ أُزْلِفَتْ', 'وَاِذَا الۡجَـنَّةُ اُزۡلِفَتۡۙ‏'),
('s81a14', 14, 81, 'عَلِمَتْ نَفْسٌ مَّآ أَحْضَرَتْ', 'عَلِمَتۡ نَفۡسٌ مَّاۤ اَحۡضَرَتۡؕ‏'),
('s81a15', 15, 81, 'فَلَآ أُقْسِمُ بِٱلْخُنَّسِ', 'فَلَاۤ اُقۡسِمُ بِالۡخُنَّسِۙ‏'),
('s81a16', 16, 81, 'ٱلْجَوَارِ ٱلْكُنَّسِ', 'الۡجَوَارِ الۡكُنَّسِۙ‏'),
('s81a17', 17, 81, 'وَٱلَّيْلِ إِذَا عَسْعَسَ', 'وَالَّيۡلِ اِذَا عَسۡعَسَۙ‏'),
('s81a18', 18, 81, 'وَٱلصُّبْحِ إِذَا تَنَفَّسَ', 'وَالصُّبۡحِ اِذَا تَنَفَّسَۙ‏'),
('s81a19', 19, 81, 'إِنَّهُۥ لَقَوْلُ رَسُولٍ كَرِيمٍ', 'اِنَّهٗ لَقَوۡلُ رَسُوۡلٍ كَرِيۡمٍۙ‏'),
('s81a20', 20, 81, 'ذِى قُوَّةٍ عِندَ ذِى ٱلْعَرْشِ مَكِينٍ', 'ذِىۡ قُوَّةٍ عِنۡدَ ذِى الۡعَرۡشِ مَكِيۡنٍۙ‏'),
('s81a21', 21, 81, 'مُّطَاعٍ ثَمَّ أَمِينٍ', 'مُّطَاعٍ ثَمَّ اَمِيۡنٍؕ‏'),
('s81a22', 22, 81, 'وَمَا صَاحِبُكُم بِمَجْنُونٍ', 'وَ مَا صَاحِبُكُمۡ بِمَجۡنُوۡنٍ​ۚ‏'),
('s81a23', 23, 81, 'وَلَقَدْ رَءَاهُ بِٱلْأُفُقِ ٱلْمُبِينِ', 'وَلَقَدۡ رَاٰهُ بِالۡاُفُقِ الۡمُبِيۡنِ​ۚ‏'),
('s81a24', 24, 81, 'وَمَا هُوَ عَلَى ٱلْغَيْبِ بِضَنِينٍ', 'وَمَا هُوَ عَلَى الۡغَيۡبِ بِضَنِيۡنٍ​ۚ‏'),
('s81a25', 25, 81, 'وَمَا هُوَ بِقَوْلِ شَيْطَـٰنٍ رَّجِيمٍ', 'وَمَا هُوَ بِقَوۡلِ شَيۡطٰنٍ رَّجِيۡمٍۙ‏'),
('s81a26', 26, 81, 'فَأَيْنَ تَذْهَبُونَ', 'فَاَيۡنَ تَذۡهَبُوۡنَؕ‏'),
('s81a27', 27, 81, 'إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَـٰلَمِينَ', 'اِنۡ هُوَ اِلَّا ذِكۡرٌ لِّلۡعٰلَمِيۡنَۙ‏'),
('s81a28', 28, 81, 'لِمَن شَآءَ مِنكُمْ أَن يَسْتَقِيمَ', 'لِمَنۡ شَآءَ مِنۡكُمۡ اَنۡ يَّسۡتَقِيۡمَؕ‏'),
('s81a29', 29, 81, 'وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلْعَـٰلَمِينَ', 'وَمَا تَشَآءُوۡنَ اِلَّاۤ اَنۡ يَّشَآءَ اللّٰهُ رَبُّ الۡعٰلَمِيۡنَ‏'),
('s82a1', 1, 82, ' إِذَا ٱلسَّمَآءُ ٱنفَطَرَتْ', 'اِذَا السَّمَآءُ انْفَطَرَتۡۙ‏'),
('s82a2', 2, 82, 'وَإِذَا ٱلْكَوَاكِبُ ٱنتَثَرَتْ', 'وَاِذَا الۡكَوَاكِبُ انْتَثَرَتۡۙ‏'),
('s82a3', 3, 82, 'وَإِذَا ٱلْبِحَارُ فُجِّرَتْ', 'وَاِذَا الۡبِحَارُ فُجِّرَتۡۙ‏'),
('s82a4', 4, 82, 'وَإِذَا ٱلْقُبُورُ بُعْثِرَتْ', 'وَاِذَا الۡقُبُوۡرُ بُعۡثِرَتۡۙ‏'),
('s82a5', 5, 82, 'عَلِمَتْ نَفْسٌ مَّا قَدَّمَتْ وَأَخَّرَتْ', 'عَلِمَتۡ نَفۡسٌ مَّا قَدَّمَتۡ وَاَخَّرَتۡؕ‏'),
('s82a6', 6, 82, 'يَـٰٓأَيُّهَا ٱلْإِنسَـٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلْكَرِيمِ', 'يٰۤاَيُّهَا الۡاِنۡسَانُ مَا غَرَّكَ بِرَبِّكَ الۡكَرِيۡمِۙ‏'),
('s82a7', 7, 82, 'ٱلَّذِى خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ', 'الَّذِىۡ خَلَقَكَ فَسَوّٰٮكَ فَعَدَلَـكَۙ‏'),
('s82a8', 8, 82, 'فِىٓ أَىِّ صُورَةٍ مَّا شَآءَ رَكَّبَكَ', 'فِىۡۤ اَىِّ صُوۡرَةٍ مَّا شَآءَ رَكَّبَكَؕ‏'),
('s82a9', 9, 82, 'كَلَّا بَلْ تُكَذِّبُونَ بِٱلدِّينِ', 'كَلَّا بَلۡ تُكَذِّبُوۡنَ بِالدِّيۡنِۙ‏'),
('s82a10', 10, 82, 'وَإِنَّ عَلَيْكُمْ لَحَـٰفِظِينَ', 'وَاِنَّ عَلَيۡكُمۡ لَحٰـفِظِيۡنَۙ‏'),
('s82a11', 11, 82, 'كِرَامًا كَـٰتِبِينَ', 'كِرَامًا كَاتِبِيۡنَۙ‏'),
('s82a12', 12, 82, 'يَعْلَمُونَ مَا تَفْعَلُونَ', 'يَعۡلَمُوۡنَ مَا تَفۡعَلُوۡنَ‏'),
('s82a13', 13, 82, 'إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ', 'اِنَّ الۡاَبۡرَارَ لَفِىۡ نَعِيۡمٍۚ‏'),
('s82a14', 14, 82, 'وَإِنَّ ٱلْفُجَّارَ لَفِى جَحِيمٍ', 'وَاِنَّ الۡفُجَّارَ لَفِىۡ جَحِيۡمٍ ۚۖ‏'),
('s82a15', 15, 82, 'يَصْلَوْنَهَا يَوْمَ ٱلدِّينِ', 'يَّصۡلَوۡنَهَا يَوۡمَ الدِّيۡنِ‏'),
('s82a16', 16, 82, 'وَمَا هُمْ عَنْهَا بِغَآئِبِينَ', 'وَمَا هُمۡ عَنۡهَا بِغَآٮِٕبِيۡنَؕ‏'),
('s82a17', 17, 82, 'وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ', 'وَمَاۤ اَدۡرٰٮكَ مَا يَوۡمُ الدِّيۡنِۙ‏'),
('s82a18', 18, 82, 'ثُمَّ مَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ', 'ثُمَّ مَاۤ اَدۡرٰٮكَ مَا يَوۡمُ الدِّيۡنِؕ‏'),
('s82a19', 19, 82, 'يَوْمَ لَا تَمْلِكُ نَفْسٌ لِّنَفْسٍ شَيْـًٔا ۖ وَٱلْأَمْرُ يَوْمَئِذٍ لِّلَّهِ', 'يَوۡمَ لَا تَمۡلِكُ نَفۡسٌ لِّنَفۡسٍ شَيۡـــًٔا​ ؕ وَالۡاَمۡرُ يَوۡمَٮِٕذٍ لِّلَّهِ‏'),
('s83a1', 1, 83, ' وَيْلٌ لِّلْمُطَفِّفِينَ', 'وَيۡلٌ لِّلۡمُطَفِّفِيۡنَۙ‏'),
('s83a2', 2, 83, 'ٱلَّذِينَ إِذَا ٱكْتَالُوا۟ عَلَى ٱلنَّاسِ يَسْتَوْفُونَ', 'الَّذِيۡنَ اِذَا اكۡتَالُوۡا عَلَى النَّاسِ يَسۡتَوۡفُوۡنَۖ‏'),
('s83a3', 3, 83, 'وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَ', 'وَاِذَا كَالُوۡهُمۡ اَوْ وَّزَنُوۡهُمۡ يُخۡسِرُوۡنَؕ‏'),
('s83a4', 4, 83, 'أَلَا يَظُنُّ أُو۟لَـٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ', 'اَلَا يَظُنُّ اُولٰٓٮِٕكَ اَنَّهُمۡ مَّبۡعُوۡثُوۡنَۙ‏'),
('s83a5', 5, 83, 'لِيَوْمٍ عَظِيمٍ', 'لِيَوۡمٍ عَظِيۡمٍۙ‏'),
('s83a6', 6, 83, 'يَوْمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلْعَـٰلَمِينَ', 'يَّوۡمَ يَقُوۡمُ النَّاسُ لِرَبِّ الۡعٰلَمِيۡنَؕ‏'),
('s83a7', 7, 83, 'كَلَّآ إِنَّ كِتَـٰبَ ٱلْفُجَّارِ لَفِى سِجِّينٍ', 'كَلَّاۤ اِنَّ كِتٰبَ الۡفُجَّارِ لَفِىۡ سِجِّيۡنٍؕ‏'),
('s83a8', 8, 83, 'وَمَآ أَدْرَىٰكَ مَا سِجِّينٌ', 'وَمَاۤ اَدۡرٰٮكَ مَا سِجِّيۡنٌؕ‏'),
('s83a9', 9, 83, 'كِتَـٰبٌ مَّرْقُومٌ', 'كِتٰبٌ مَّرۡقُوۡمٌؕ‏'),
('s83a10', 10, 83, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيۡلٌ يَّوۡمَٮِٕذٍ لِّلۡمُكَذِّبِيۡنَۙ‏'),
('s83a11', 11, 83, 'ٱلَّذِينَ يُكَذِّبُونَ بِيَوْمِ ٱلدِّينِ', 'الَّذِيۡنَ يُكَذِّبُوۡنَ بِيَوۡمِ الدِّيۡنِؕ‏'),
('s83a12', 12, 83, 'وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعْتَدٍ أَثِيمٍ', 'وَمَا يُكَذِّبُ بِهٖۤ اِلَّا كُلُّ مُعۡتَدٍ اَثِيۡمٍۙ‏'),
('s83a13', 13, 83, 'إِذَا تُتْلَىٰ عَلَيْهِ ءَايَـٰتُنَا قَالَ أَسَـٰطِيرُ ٱلْأَوَّلِينَ', 'اِذَا تُتۡلٰى عَلَيۡهِ اٰيٰتُنَا قَالَ اَسَاطِيۡرُ الۡاَوَّلِيۡنَؕ‏'),
('s83a14', 14, 83, 'كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا۟ يَكْسِبُونَ', 'كَلَّا​ بَلۡ رَانَ عَلٰى قُلُوۡبِهِمۡ مَّا كَانُوۡا يَكۡسِبُوۡنَ‏'),
('s83a15', 15, 83, 'كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍ لَّمَحْجُوبُونَ', 'كَلَّاۤ اِنَّهُمۡ عَنۡ رَّبِّهِمۡ يَوۡمَٮِٕذٍ لَّمَحۡجُوۡبُوۡنَ​ؕ‏'),
('s83a16', 16, 83, 'ثُمَّ إِنَّهُمْ لَصَالُوا۟ ٱلْجَحِيمِ', 'ثُمَّ اِنَّهُمۡ لَصَالُوا الۡجَحِيۡمِؕ‏'),
('s83a17', 17, 83, 'ثُمَّ يُقَالُ هَـٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', 'ثُمَّ يُقَالُ هٰذَا الَّذِىۡ كُنۡتُمۡ بِهٖ تُكَذِّبُوۡنَؕ‏'),
('s83a18', 18, 83, 'كَلَّآ إِنَّ كِتَـٰبَ ٱلْأَبْرَارِ لَفِى عِلِّيِّينَ', 'كَلَّاۤ اِنَّ كِتٰبَ الۡاَبۡرَارِ لَفِىۡ عِلِّيِّيۡنَؕ‏'),
('s83a19', 19, 83, 'وَمَآ أَدْرَىٰكَ مَا عِلِّيُّونَ', 'وَمَاۤ اَدۡرٰٮكَ مَا عِلِّيُّوۡنَؕ‏'),
('s83a20', 20, 83, 'كِتَـٰبٌ مَّرْقُومٌ', 'كِتٰبٌ مَّرۡقُوۡمٌۙ‏'),
('s83a21', 21, 83, 'يَشْهَدُهُ ٱلْمُقَرَّبُونَ', 'يَّشۡهَدُهُ الۡمُقَرَّبُوۡنَؕ‏'),
('s83a22', 22, 83, 'إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ', 'اِنَّ الۡاَبۡرَارَ لَفِىۡ نَعِيۡمٍۙ‏'),
('s83a23', 23, 83, 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', 'عَلَى الۡاَرَآٮِٕكِ يَنۡظُرُوۡنَۙ‏'),
('s83a24', 24, 83, 'تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ ٱلنَّعِيمِ', 'تَعۡرِفُ فِىۡ وُجُوۡهِهِمۡ نَضۡرَةَ النَّعِيۡمِ​ۚ‏'),
('s83a25', 25, 83, 'يُسْقَوْنَ مِن رَّحِيقٍ مَّخْتُومٍ', 'يُسۡقَوۡنَ مِنۡ رَّحِيۡقٍ مَّخۡتُوۡمٍۙ‏'),
('s83a26', 26, 83, 'خِتَـٰمُهُۥ مِسْكٌ ۚ وَفِى ذَٰلِكَ فَلْيَتَنَافَسِ ٱلْمُتَنَـٰفِسُونَ', 'خِتٰمُهٗ مِسۡكٌ ​ؕ وَفِىۡ ذٰلِكَ فَلۡيَتَنَافَسِ الۡمُتَنــَافِسُوۡنَؕ‏'),
('s83a27', 27, 83, 'وَمِزَاجُهُۥ مِن تَسْنِيمٍ', 'وَ مِزَاجُهٗ مِنۡ تَسۡنِيۡمٍۙ‏'),
('s83a28', 28, 83, 'عَيْنًا يَشْرَبُ بِهَا ٱلْمُقَرَّبُونَ', 'عَيۡنًا يَّشۡرَبُ بِهَا الۡمُقَرَّبُوۡنَؕ‏'),
('s83a29', 29, 83, 'إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ', 'اِنَّ الَّذِيۡنَ اَجۡرَمُوۡا كَانُوۡا مِنَ الَّذِيۡنَ اٰمَنُوۡا يَضۡحَكُوۡنَ  ۖ‏'),
('s83a30', 30, 83, 'وَإِذَا مَرُّوا۟ بِهِمْ يَتَغَامَزُونَ', 'وَاِذَا مَرُّوۡا بِهِمۡ يَتَغَامَزُوۡنَ  ۖ‏'),
('s83a31', 31, 83, 'وَإِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمُ ٱنقَلَبُوا۟ فَكِهِينَ', 'وَاِذَا انۡقَلَبُوۡۤا اِلٰٓى اَهۡلِهِمُ انْقَلَبُوۡا فَكِهِيۡنَ  ۖ‏'),
('s83a32', 32, 83, 'وَإِذَا رَأَوْهُمْ قَالُوٓا۟ إِنَّ هَـٰٓؤُلَآءِ لَضَآلُّونَ', 'وَاِذَا رَاَوۡهُمۡ قَالُوۡۤا اِنَّ هٰٓؤُلَاۤءِ لَـضَآلُّوۡنَۙ‏'),
('s83a33', 33, 83, 'وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَـٰفِظِينَ', 'وَمَاۤ اُرۡسِلُوۡا عَلَيۡهِمۡ حٰفِظِيۡنَۙ‏'),
('s83a34', 34, 83, 'فَٱلْيَوْمَ ٱلَّذِينَ ءَامَنُوا۟ مِنَ ٱلْكُفَّارِ يَضْحَكُونَ', 'فَالۡيَوۡمَ الَّذِيۡنَ اٰمَنُوۡا مِنَ الۡكُفَّارِ يَضۡحَكُوۡنَۙ‏'),
('s83a35', 35, 83, 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', 'عَلَى الۡاَرَآٮِٕكِۙ يَنۡظُرُوۡنَؕ‏'),
('s83a36', 36, 83, 'هَلْ ثُوِّبَ ٱلْكُفَّارُ مَا كَانُوا۟ يَفْعَلُونَ', 'هَلۡ ثُوِّبَ الۡكُفَّارُ مَا كَانُوۡا يَفۡعَلُوۡنَ‏'),
('s84a1', 1, 84, ' إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ', 'اِذَا السَّمَآءُ انْشَقَّتۡۙ‏'),
('s84a2', 2, 84, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 'وَاَذِنَتۡ لِرَبِّهَا وَحُقَّتۡۙ‏'),
('s84a3', 3, 84, 'وَإِذَا ٱلْأَرْضُ مُدَّتْ', 'وَاِذَا الۡاَرۡضُ مُدَّتۡؕ‏'),
('s84a4', 4, 84, 'وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ', 'وَاَلۡقَتۡ مَا فِيۡهَا وَتَخَلَّتۡۙ‏'),
('s84a5', 5, 84, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 'وَاَذِنَتۡ لِرَبِّهَا وَحُقَّتۡؕ‏'),
('s84a6', 6, 84, 'يَـٰٓأَيُّهَا ٱلْإِنسَـٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًا فَمُلَـٰقِيهِ', 'يٰۤاَيُّهَا الۡاِنۡسَانُ اِنَّكَ كَادِحٌ اِلٰى رَبِّكَ كَدۡحًا فَمُلٰقِيۡهِ​ۚ‏ ﻿﻿'),
('s84a7', 7, 84, 'فَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ بِيَمِينِهِۦ', 'فَاَمَّا مَنۡ اُوۡتِىَ كِتٰبَهٗ بِيَمِيۡنِهٖۙ‏'),
('s84a8', 8, 84, 'فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا', 'فَسَوۡفَ يُحَاسَبُ حِسَابًا يَّسِيۡرًا ۙ‏'),
('s84a9', 9, 84, 'وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُورًا', 'وَّيَنۡقَلِبُ اِلٰٓى اَهۡلِهٖ مَسۡرُوۡرًا ؕ‏'),
('s84a10', 10, 84, 'وَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ وَرَآءَ ظَهْرِهِۦ', 'وَاَمَّا مَنۡ اُوۡتِىَ كِتٰبَهٗ وَرَآءَ ظَهۡرِهٖۙ‏'),
('s84a11', 11, 84, 'فَسَوْفَ يَدْعُوا۟ ثُبُورًا', 'فَسَوۡفَ يَدۡعُوۡا ثُبُوۡرًا ۙ‏'),
('s84a12', 12, 84, 'وَيَصْلَىٰ سَعِيرًا', 'وَّيَصۡلٰى سَعِيۡرًا ؕ‏'),
('s84a13', 13, 84, 'إِنَّهُۥ كَانَ فِىٓ أَهْلِهِۦ مَسْرُورًا', 'اِنَّهٗ كَانَ فِىۡۤ اَهۡلِهٖ مَسۡرُوۡرًا ؕ‏'),
('s84a14', 14, 84, 'إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ', 'اِنَّهٗ ظَنَّ اَنۡ لَّنۡ يَّحُوۡرَ ۛۚ‏'),
('s84a15', 15, 84, 'بَلَىٰٓ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرًا', 'بَلٰٓى ۛۚ اِنَّ رَبَّهٗ كَانَ بِهٖ بَصِيۡرًا ؕ‏'),
('s84a16', 16, 84, 'فَلَآ أُقْسِمُ بِٱلشَّفَقِ', 'فَلَاۤ اُقۡسِمُ بِالشَّفَقِۙ‏'),
('s84a17', 17, 84, 'وَٱلَّيْلِ وَمَا وَسَقَ', 'وَالَّيۡلِ وَمَا وَسَقَۙ‏'),
('s84a18', 18, 84, 'وَٱلْقَمَرِ إِذَا ٱتَّسَقَ', 'وَالۡقَمَرِ اِذَا اتَّسَقَۙ‏'),
('s84a19', 19, 84, 'لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍ', 'لَتَرۡكَبُنَّ طَبَقًا عَنۡ طَبَقٍؕ‏'),
('s84a20', 20, 84, 'فَمَا لَهُمْ لَا يُؤْمِنُونَ', 'فَمَا لَهُمۡ لَا يُؤۡمِنُوۡنَۙ‏'),
('s84a21', 21, 84, 'وَإِذَا قُرِئَ عَلَيْهِمُ ٱلْقُرْءَانُ لَا يَسْجُدُونَ ۩', 'وَاِذَا قُرِئَ عَلَيۡهِمُ الۡقُرۡاٰنُ لَا يَسۡجُدُوۡنَ ؕ ۩‏'),
('s84a22', 22, 84, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ يُكَذِّبُونَ', 'بَلِ الَّذِيۡنَ كَفَرُوۡا يُكَذِّبُوۡنَ ۖ‏'),
('s84a23', 23, 84, 'وَٱللَّهُ أَعْلَمُ بِمَا يُوعُونَ', 'وَاللّٰهُ اَعۡلَمُ بِمَا يُوۡعُوۡنَ ۖ‏'),
('s84a24', 24, 84, 'فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', 'فَبَشِّرۡهُمۡ بِعَذَابٍ اَلِيۡمٍۙ‏'),
('s84a25', 25, 84, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ', 'اِلَّا الَّذِيۡنَ اٰمَنُوۡا وَعَمِلُوا الصّٰلِحٰتِ لَهُمۡ اَجۡرٌ غَيۡرُ مَمۡنُوۡنٍ‏ ﻿﻿'),
('s85a1', 1, 85, ' وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ', 'وَالسَّمَآءِ ذَاتِ الۡبُرُوۡجِۙ‏'),
('s85a2', 2, 85, 'وَٱلْيَوْمِ ٱلْمَوْعُودِ', 'وَالۡيَوۡمِ الۡمَوۡعُوۡدِۙ‏'),
('s85a3', 3, 85, 'وَشَاهِدٍ وَمَشْهُودٍ', 'وَشَاهِدٍ وَّمَشۡهُوۡدٍؕ‏'),
('s85a4', 4, 85, 'قُتِلَ أَصْحَـٰبُ ٱلْأُخْدُودِ', 'قُتِلَ اَصۡحٰبُ الۡاُخۡدُوۡدِۙ‏'),
('s85a5', 5, 85, 'ٱلنَّارِ ذَاتِ ٱلْوَقُودِ', 'النَّارِ ذَاتِ الۡوَقُوۡدِۙ‏'),
('s85a6', 6, 85, 'إِذْ هُمْ عَلَيْهَا قُعُودٌ', 'اِذۡ هُمۡ عَلَيۡهَا قُعُوۡدٌ ۙ‏'),
('s85a7', 7, 85, 'وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِٱلْمُؤْمِنِينَ شُهُودٌ', 'وَّهُمۡ عَلٰى مَا يَفۡعَلُوۡنَ بِالۡمُؤۡمِنِيۡنَ شُهُوۡدٌ ؕ‏'),
('s85a8', 8, 85, 'وَمَا نَقَمُوا۟ مِنْهُمْ إِلَّآ أَن يُؤْمِنُوا۟ بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 'وَمَا نَقَمُوۡا مِنۡهُمۡ اِلَّاۤ اَنۡ يُّؤۡمِنُوۡا بِاللّٰهِ الۡعَزِيۡزِ الۡحَمِيۡدِۙ‏ ﻿﻿'),
('s85a9', 9, 85, 'ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'الَّذِىۡ لَهٗ مُلۡكُ السَّمٰوٰتِ وَالۡاَرۡضِ​ؕ وَ اللّٰهُ عَلٰى كُلِّ شَىۡءٍ شَهِيۡدٌ ؕ‏'),
('s85a10', 10, 85, 'إِنَّ ٱلَّذِينَ فَتَنُوا۟ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ ثُمَّ لَمْ يَتُوبُوا۟ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ٱلْحَرِيقِ', 'اِنَّ الَّذِيۡنَ فَتَـنُوا الۡمُؤۡمِنِيۡنَ وَ الۡمُؤۡمِنٰتِ ثُمَّ لَمۡ يَتُوۡبُوۡا فَلَهُمۡ عَذَابُ جَهَنَّمَ وَلَهُمۡ عَذَابُ الۡحَرِيۡقِؕ‏'),
('s85a11', 11, 85, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْكَبِيرُ', 'اِنَّ الَّذِيۡنَ اٰمَنُوۡا وَعَمِلُوا الصّٰلِحٰتِ لَهُمۡ جَنّٰتٌ تَجۡرِىۡ مِنۡ تَحۡتِهَا الۡاَنۡهٰرُ ؕ ذٰلِكَ الۡفَوۡزُ الۡكَبِيۡرُؕ‏'),
('s85a12', 12, 85, 'إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ', 'اِنَّ بَطۡشَ رَبِّكَ لَشَدِيۡدٌ ؕ‏'),
('s85a13', 13, 85, 'إِنَّهُۥ هُوَ يُبْدِئُ وَيُعِيدُ', 'اِنَّهٗ هُوَ يُبۡدِئُ وَيُعِيۡدُ​ ۚ‏'),
('s85a14', 14, 85, 'وَهُوَ ٱلْغَفُورُ ٱلْوَدُودُ', 'وَهُوَ الۡغَفُوۡرُ الۡوَدُوۡدُۙ‏'),
('s85a15', 15, 85, 'ذُو ٱلْعَرْشِ ٱلْمَجِيدُ', 'ذُو الۡعَرۡشِ الۡمَجِيۡدُ ۙ‏'),
('s85a16', 16, 85, 'فَعَّالٌ لِّمَا يُرِيدُ', 'فَعَّالٌ لِّمَا يُرِيۡدُ ؕ‏'),
('s85a17', 17, 85, 'هَلْ أَتَىٰكَ حَدِيثُ ٱلْجُنُودِ', 'هَلۡ اَتٰٮكَ حَدِيۡثُ الۡجُـنُوۡدِۙ‏'),
('s85a18', 18, 85, 'فِرْعَوْنَ وَثَمُودَ', 'فِرۡعَوۡنَ وَثَمُوۡدَؕ‏'),
('s85a19', 19, 85, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى تَكْذِيبٍ', 'بَلِ الَّذِيۡنَ كَفَرُوۡا فِىۡ تَكۡذِيۡبٍۙ‏'),
('s85a20', 20, 85, 'وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطٌۢ', 'وَّاللّٰهُ مِنۡ وَّرَآٮِٕهِمۡ مُّحِيۡطٌۚ‏'),
('s85a21', 21, 85, 'بَلْ هُوَ قُرْءَانٌ مَّجِيدٌ', 'بَلۡ هُوَ قُرۡاٰنٌ مَّجِيۡدٌ ۙ‏'),
('s85a22', 22, 85, 'فِى لَوْحٍ مَّحْفُوظٍۭ', 'فِىۡ لَوۡحٍ مَّحۡفُوۡظٍ‏'),
('s86a1', 1, 86, ' وَٱلسَّمَآءِ وَٱلطَّارِقِ', 'وَالسَّمَآءِ وَالطَّارِقِۙ‏'),
('s86a2', 2, 86, 'وَمَآ أَدْرَىٰكَ مَا ٱلطَّارِقُ', 'وَمَاۤ اَدۡرٰٮكَ مَا الطَّارِقُۙ‏'),
('s86a3', 3, 86, 'ٱلنَّجْمُ ٱلثَّاقِبُ', 'النَّجۡمُ الثَّاقِبُۙ‏'),
('s86a4', 4, 86, 'إِن كُلُّ نَفْسٍ لَّمَّا عَلَيْهَا حَافِظٌ', 'اِنۡ كُلُّ نَفۡسٍ لَّمَّا عَلَيۡهَا حَافِظٌؕ‏'),
('s86a5', 5, 86, 'فَلْيَنظُرِ ٱلْإِنسَـٰنُ مِمَّ خُلِقَ', 'فَلۡيَنۡظُرِ الۡاِنۡسَانُ مِمَّ خُلِقَؕ‏'),
('s86a6', 6, 86, 'خُلِقَ مِن مَّآءٍ دَافِقٍ', 'خُلِقَ مِنۡ مَّآءٍ دَافِقٍۙ‏'),
('s86a7', 7, 86, 'يَخْرُجُ مِنۢ بَيْنِ ٱلصُّلْبِ وَٱلتَّرَآئِبِ', 'يَّخۡرُجُ مِنۡۢ بَيۡنِ الصُّلۡبِ وَالتَّرَآٮِٕبِؕ‏'),
('s86a8', 8, 86, 'إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٌ', 'اِنَّهٗ عَلٰى رَجۡعِهٖ لَقَادِرٌؕ‏'),
('s86a9', 9, 86, 'يَوْمَ تُبْلَى ٱلسَّرَآئِرُ', 'يَوۡمَ تُبۡلَى السَّرَآٮِٕرُۙ‏'),
('s86a10', 10, 86, 'فَمَا لَهُۥ مِن قُوَّةٍ وَلَا نَاصِرٍ', 'فَمَا لَهٗ مِنۡ قُوَّةٍ وَّلَا نَاصِرٍؕ‏'),
('s86a11', 11, 86, 'وَٱلسَّمَآءِ ذَاتِ ٱلرَّجْعِ', 'وَالسَّمَآءِ ذَاتِ الرَّجۡعِۙ‏'),
('s86a12', 12, 86, 'وَٱلْأَرْضِ ذَاتِ ٱلصَّدْعِ', 'وَالۡاَرۡضِ ذَاتِ الصَّدۡعِۙ‏'),
('s86a13', 13, 86, 'إِنَّهُۥ لَقَوْلٌ فَصْلٌ', 'اِنَّهٗ لَقَوۡلٌ فَصۡلٌۙ‏'),
('s86a14', 14, 86, 'وَمَا هُوَ بِٱلْهَزْلِ', 'وَّمَا هُوَ بِالۡهَزۡلِؕ‏'),
('s86a15', 15, 86, 'إِنَّهُمْ يَكِيدُونَ كَيْدًا', 'اِنَّهُمۡ يَكِيۡدُوۡنَ كَيۡدًا ۙ‏'),
('s86a16', 16, 86, 'وَأَكِيدُ كَيْدًا', 'وَّاَكِيۡدُ كَيۡدًا ۚۖ‏'),
('s86a17', 17, 86, 'فَمَهِّلِ ٱلْكَـٰفِرِينَ أَمْهِلْهُمْ رُوَيْدًۢا', 'فَمَهِّلِ الۡكٰفِرِيۡنَ اَمۡهِلۡهُمۡ رُوَيۡدًا‏'),
('s87a1', 1, 87, ' سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى', 'سَبِّحِ اسۡمَ رَبِّكَ الۡاَعۡلَىۙ‏'),
('s87a2', 2, 87, 'ٱلَّذِى خَلَقَ فَسَوَّىٰ', 'الَّذِىۡ خَلَقَ فَسَوّٰى ۙ‏'),
('s87a3', 3, 87, 'وَٱلَّذِى قَدَّرَ فَهَدَىٰ', 'وَالَّذِىۡ قَدَّرَ فَهَدٰى ۙ‏'),
('s87a4', 4, 87, 'وَٱلَّذِىٓ أَخْرَجَ ٱلْمَرْعَىٰ', 'وَالَّذِىۡۤ اَخۡرَجَ الۡمَرۡعٰى ۙ‏'),
('s87a5', 5, 87, 'فَجَعَلَهُۥ غُثَآءً أَحْوَىٰ', 'فَجَعَلَهٗ غُثَآءً اَحۡوٰىؕ‏'),
('s87a6', 6, 87, 'سَنُقْرِئُكَ فَلَا تَنسَىٰٓ', 'سَنُقۡرِئُكَ فَلَا تَنۡسٰٓىۙ‏'),
('s87a7', 7, 87, 'إِلَّا مَا شَآءَ ٱللَّهُ ۚ إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ وَمَا يَخْفَىٰ', 'اِلَّا مَا شَآءَ اللّٰهُ​ؕ اِنَّهٗ يَعۡلَمُ الۡجَهۡرَ وَمَا يَخۡفٰىؕ‏'),
('s87a8', 8, 87, 'وَنُيَسِّرُكَ لِلْيُسْرَىٰ', 'وَنُيَسِّرُكَ لِلۡيُسۡرٰى ​ۖ​ۚ‏'),
('s87a9', 9, 87, 'فَذَكِّرْ إِن نَّفَعَتِ ٱلذِّكْرَىٰ', 'فَذَكِّرۡ اِنۡ نَّفَعَتِ الذِّكۡرٰىؕ‏'),
('s87a10', 10, 87, 'سَيَذَّكَّرُ مَن يَخْشَىٰ', 'سَيَذَّكَّرُ مَنۡ يَّخۡشٰىۙ‏'),
('s87a11', 11, 87, 'وَيَتَجَنَّبُهَا ٱلْأَشْقَى', 'وَيَتَجَنَّبُهَا الۡاَشۡقَىۙ‏'),
('s87a12', 12, 87, 'ٱلَّذِى يَصْلَى ٱلنَّارَ ٱلْكُبْرَىٰ', 'الَّذِىۡ يَصۡلَى النَّارَ الۡكُبۡرٰى​ۚ‏'),
('s87a13', 13, 87, 'ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ', 'ثُمَّ لَا يَمُوۡتُ فِيۡهَا وَلَا يَحۡيٰىؕ‏'),
('s87a14', 14, 87, 'قَدْ أَفْلَحَ مَن تَزَكَّىٰ', 'قَدۡ اَفۡلَحَ مَنۡ تَزَكّٰىۙ‏'),
('s87a15', 15, 87, 'وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ', 'وَذَكَرَ اسۡمَ رَبِّهٖ فَصَلّٰى​ ؕ‏'),
('s87a16', 16, 87, 'بَلْ تُؤْثِرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا', 'بَلۡ تُؤۡثِرُوۡنَ الۡحَيٰوةَ الدُّنۡيَا ۖ‏'),
('s87a17', 17, 87, 'وَٱلْـَٔاخِرَةُ خَيْرٌ وَأَبْقَىٰٓ', 'وَالۡاٰخِرَةُ خَيۡرٌ وَّ اَبۡقٰىؕ‏'),
('s87a18', 18, 87, 'إِنَّ هَـٰذَا لَفِى ٱلصُّحُفِ ٱلْأُولَىٰ', 'اِنَّ هٰذَا لَفِى الصُّحُفِ الۡاُوۡلٰىۙ‏'),
('s87a19', 19, 87, 'صُحُفِ إِبْرَٰهِيمَ وَمُوسَىٰ', 'صُحُفِ اِبۡرٰهِيۡمَ وَمُوۡسٰى‏'),
('s88a1', 1, 88, ' هَلْ أَتَىٰكَ حَدِيثُ ٱلْغَـٰشِيَةِ', 'هَلۡ اَتٰٮكَ حَدِيۡثُ الۡغَاشِيَةِؕ‏'),
('s88a2', 2, 88, 'وُجُوهٌ يَوْمَئِذٍ خَـٰشِعَةٌ', 'وُجُوۡهٌ يَّوۡمَٮِٕذٍ خَاشِعَةٌ ۙ‏'),
('s88a3', 3, 88, 'عَامِلَةٌ نَّاصِبَةٌ', 'عَامِلَةٌ نَّاصِبَةٌ ۙ‏'),
('s88a4', 4, 88, 'تَصْلَىٰ نَارًا حَامِيَةً', 'تَصۡلٰى نَارًا حَامِيَةً ۙ‏'),
('s88a5', 5, 88, 'تُسْقَىٰ مِنْ عَيْنٍ ءَانِيَةٍ', 'تُسۡقٰى مِنۡ عَيۡنٍ اٰنِيَةٍؕ‏'),
('s88a6', 6, 88, 'لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٍ', 'لَـيۡسَ لَهُمۡ طَعَامٌ اِلَّا مِنۡ ضَرِيۡعٍۙ‏'),
('s88a7', 7, 88, 'لَّا يُسْمِنُ وَلَا يُغْنِى مِن جُوعٍ', 'لَّا يُسۡمِنُ وَلَا يُغۡنِىۡ مِنۡ جُوۡعٍؕ‏'),
('s88a8', 8, 88, 'وُجُوهٌ يَوْمَئِذٍ نَّاعِمَةٌ', 'وُجُوۡهٌ يَّوۡمَٮِٕذٍ نَّاعِمَةٌ ۙ‏'),
('s88a9', 9, 88, 'لِّسَعْيِهَا رَاضِيَةٌ', 'لِّسَعۡيِهَا رَاضِيَةٌ ۙ‏'),
('s88a10', 10, 88, 'فِى جَنَّةٍ عَالِيَةٍ', 'فِىۡ جَنَّةٍ عَالِيَةٍۙ‏'),
('s88a11', 11, 88, 'لَّا تَسْمَعُ فِيهَا لَـٰغِيَةً', 'لَّا تَسۡمَعُ فِيۡهَا لَاغِيَةً ؕ‏'),
('s88a12', 12, 88, 'فِيهَا عَيْنٌ جَارِيَةٌ', 'فِيۡهَا عَيۡنٌ جَارِيَةٌ​ ۘ‏'),
('s88a13', 13, 88, 'فِيهَا سُرُرٌ مَّرْفُوعَةٌ', 'فِيۡهَا سُرُرٌ مَّرۡفُوۡعَةٌ ۙ‏'),
('s88a14', 14, 88, 'وَأَكْوَابٌ مَّوْضُوعَةٌ', 'وَّاَكۡوَابٌ مَّوۡضُوۡعَةٌ ۙ‏'),
('s88a15', 15, 88, 'وَنَمَارِقُ مَصْفُوفَةٌ', 'وَّنَمَارِقُ مَصۡفُوۡفَةٌ ۙ‏'),
('s88a16', 16, 88, 'وَزَرَابِىُّ مَبْثُوثَةٌ', 'وَّزَرَابِىُّ مَبۡثُوۡثَةٌ ؕ‏'),
('s88a17', 17, 88, 'أَفَلَا يَنظُرُونَ إِلَى ٱلْإِبِلِ كَيْفَ خُلِقَتْ', 'اَفَلَا يَنۡظُرُوۡنَ اِلَى الۡاِ بِلِ كَيۡفَ خُلِقَتۡ‏'),
('s88a18', 18, 88, 'وَإِلَى ٱلسَّمَآءِ كَيْفَ رُفِعَتْ', 'وَاِلَى السَّمَآءِ كَيۡفَ رُفِعَتۡ‏'),
('s88a19', 19, 88, 'وَإِلَى ٱلْجِبَالِ كَيْفَ نُصِبَتْ', 'وَاِلَى الۡجِبَالِ كَيۡفَ نُصِبَتۡ‏'),
('s88a20', 20, 88, 'وَإِلَى ٱلْأَرْضِ كَيْفَ سُطِحَتْ', 'وَاِلَى الۡاَرۡضِ كَيۡفَ سُطِحَتۡ‏'),
('s88a21', 21, 88, 'فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌ', 'فَذَكِّرۡ ؕ اِنَّمَاۤ اَنۡتَ مُذَكِّرٌ ؕ‏'),
('s88a22', 22, 88, 'لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ', 'لَـسۡتَ عَلَيۡهِمۡ بِمُصَۜيۡطِرٍۙ‏'),
('s88a23', 23, 88, 'إِلَّا مَن تَوَلَّىٰ وَكَفَرَ', 'اِلَّا مَنۡ تَوَلّٰى وَكَفَرَۙ‏'),
('s88a24', 24, 88, 'فَيُعَذِّبُهُ ٱللَّهُ ٱلْعَذَابَ ٱلْأَكْبَرَ', 'فَيُعَذِّبُهُ اللّٰهُ الۡعَذَابَ الۡاَكۡبَرَؕ‏'),
('s88a25', 25, 88, 'إِنَّ إِلَيْنَآ إِيَابَهُمْ', 'اِنَّ اِلَيۡنَاۤ اِيَابَهُمۡۙ‏'),
('s88a26', 26, 88, 'ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم', 'ثُمَّ اِنَّ عَلَيۡنَا حِسَابَهُمْ‏'),
('s89a1', 1, 89, ' وَٱلْفَجْرِ', 'وَالۡفَجۡرِۙ‏'),
('s89a2', 2, 89, 'وَلَيَالٍ عَشْرٍ', 'وَلَيَالٍ عَشۡرٍۙ‏'),
('s89a3', 3, 89, 'وَٱلشَّفْعِ وَٱلْوَتْرِ', 'وَّالشَّفۡعِ وَالۡوَتۡرِۙ‏'),
('s89a4', 4, 89, 'وَٱلَّيْلِ إِذَا يَسْرِ', 'وَالَّيۡلِ اِذَا يَسۡرِ​ۚ‏'),
('s89a5', 5, 89, 'هَلْ فِى ذَٰلِكَ قَسَمٌ لِّذِى حِجْرٍ', 'هَلۡ فِىۡ ذٰلِكَ قَسَمٌ لِّذِىۡ حِجۡرٍؕ‏'),
('s89a6', 6, 89, 'أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ', 'اَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِعَادٍۙ‏'),
('s89a7', 7, 89, 'إِرَمَ ذَاتِ ٱلْعِمَادِ', 'اِرَمَ ذَاتِ الۡعِمَادِۙ‏'),
('s89a8', 8, 89, 'ٱلَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى ٱلْبِلَـٰدِ', 'الَّتِىۡ لَمۡ يُخۡلَقۡ مِثۡلُهَا فِى الۡبِلَادِۙ‏'),
('s89a9', 9, 89, 'وَثَمُودَ ٱلَّذِينَ جَابُوا۟ ٱلصَّخْرَ بِٱلْوَادِ', 'وَثَمُوۡدَ الَّذِيۡنَ جَابُوا الصَّخۡرَ بِالۡوَادِۙ‏'),
('s89a10', 10, 89, 'وَفِرْعَوْنَ ذِى ٱلْأَوْتَادِ', 'وَفِرۡعَوۡنَ ذِى الۡاَوۡتَادِۙ‏'),
('s89a11', 11, 89, 'ٱلَّذِينَ طَغَوْا۟ فِى ٱلْبِلَـٰدِ', 'الَّذِيۡنَ طَغَوۡا فِى الۡبِلَادِۙ‏'),
('s89a12', 12, 89, 'فَأَكْثَرُوا۟ فِيهَا ٱلْفَسَادَ', 'فَاَكۡثَرُوۡا فِيۡهَا الۡفَسَادَۙ‏'),
('s89a13', 13, 89, 'فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ', 'فَصَبَّ عَلَيۡهِمۡ رَبُّكَ سَوۡطَ عَذَابٍ ۙۚ‏'),
('s89a14', 14, 89, 'إِنَّ رَبَّكَ لَبِٱلْمِرْصَادِ', 'اِنَّ رَبَّكَ لَبِالۡمِرۡصَادِؕ‏'),
('s89a15', 15, 89, 'فَأَمَّا ٱلْإِنسَـٰنُ إِذَا مَا ٱبْتَلَىٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّىٓ أَكْرَمَنِ', 'فَاَمَّا الۡاِنۡسَانُ اِذَا مَا ابۡتَلٰٮهُ رَبُّهٗ فَاَكۡرَمَهٗ وَنَعَّمَهٗ  ۙ فَيَقُوۡلُ رَبِّىۡۤ اَكۡرَمَنِؕ‏'),
('s89a16', 16, 89, 'وَأَمَّآ إِذَا مَا ٱبْتَلَىٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ فَيَقُولُ رَبِّىٓ أَهَـٰنَنِ', 'وَاَمَّاۤ اِذَا مَا ابۡتَلٰٮهُ فَقَدَرَ عَلَيۡهِ رِزۡقَهٗ ۙ فَيَقُوۡلُ رَبِّىۡۤ اَهَانَنِ​ۚ‏'),
('s89a17', 17, 89, 'كَلَّا ۖ بَل لَّا تُكْرِمُونَ ٱلْيَتِيمَ', 'كَلَّا​ بَلۡ لَّا تُكۡرِمُوۡنَ الۡيَتِيۡمَۙ‏'),
('s89a18', 18, 89, 'وَلَا تَحَـٰٓضُّونَ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 'وَلَا تَحٰٓضُّوۡنَ عَلٰى طَعَامِ الۡمِسۡكِيۡنِۙ‏'),
('s89a19', 19, 89, 'وَتَأْكُلُونَ ٱلتُّرَاثَ أَكْلًا لَّمًّا', 'وَتَاۡكُلُوۡنَ التُّرَاثَ اَكۡلًا لَّـمًّا ۙ‏'),
('s89a20', 20, 89, 'وَتُحِبُّونَ ٱلْمَالَ حُبًّا جَمًّا', 'وَّتُحِبُّوۡنَ الۡمَالَ حُبًّا جَمًّا ؕ‏'),
('s89a21', 21, 89, 'كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّا دَكًّا', 'كَلَّاۤ اِذَا دُكَّتِ الۡاَرۡضُ دَكًّا دَكًّا ۙ‏'),
('s89a22', 22, 89, 'وَجَآءَ رَبُّكَ وَٱلْمَلَكُ صَفًّا صَفًّا', 'وَّجَآءَ رَبُّكَ وَالۡمَلَكُ صَفًّا صَفًّا ۚ‏'),
('s89a23', 23, 89, 'وَجِا۟ىٓءَ يَوْمَئِذٍۭ بِجَهَنَّمَ ۚ يَوْمَئِذٍ يَتَذَكَّرُ ٱلْإِنسَـٰنُ وَأَنَّىٰ لَهُ ٱلذِّكْرَىٰ', 'وَجِاىْٓءَ يَوۡمَٮِٕذٍۢ بِجَهَنَّمَ  ۙ​ يَوۡمَٮِٕذٍ يَّتَذَكَّرُ الۡاِنۡسَانُ وَاَنّٰى لَـهُ الذِّكۡرٰىؕ‏'),
('s89a24', 24, 89, 'يَقُولُ يَـٰلَيْتَنِى قَدَّمْتُ لِحَيَاتِى', 'يَقُوۡلُ يٰلَيۡتَنِىۡ قَدَّمۡتُ لِحَـيَاتِى​ۚ‏'),
('s89a25', 25, 89, 'فَيَوْمَئِذٍ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌ', 'فَيَوۡمَٮِٕذٍ لَّا يُعَذِّبُ عَذَابَهٗۤ اَحَدٌ ۙ‏'),
('s89a26', 26, 89, 'وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌ', 'وَّلَا يُوۡثِقُ وَثَاقَهٗۤ اَحَدٌ ؕ‏'),
('s89a27', 27, 89, 'يَـٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ', 'يٰۤاَيَّتُهَا النَّفۡسُ الۡمُطۡمَٮِٕنَّةُ  ۖ‏'),
('s89a28', 28, 89, 'ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةً مَّرْضِيَّةً', 'ارۡجِعِىۡۤ اِلٰى رَبِّكِ رَاضِيَةً مَّرۡضِيَّةً​ ۚ‏'),
('s89a29', 29, 89, 'فَٱدْخُلِى فِى عِبَـٰدِى', 'فَادۡخُلِىۡ فِىۡ عِبٰدِىۙ‏'),
('s89a30', 30, 89, 'وَٱدْخُلِى جَنَّتِى', 'وَادۡخُلِىۡ جَنَّتِى‏'),
('s90a1', 1, 90, ' لَآ أُقْسِمُ بِهَـٰذَا ٱلْبَلَدِ', 'لَاۤ اُقۡسِمُ بِهٰذَا الۡبَلَدِۙ‏'),
('s90a2', 2, 90, 'وَأَنتَ حِلٌّۢ بِهَـٰذَا ٱلْبَلَدِ', 'وَاَنۡتَ حِلٌّ ۢ بِهٰذَا الۡبَلَدِۙ‏'),
('s90a3', 3, 90, 'وَوَالِدٍ وَمَا وَلَدَ', 'وَوَالِدٍ وَّمَا وَلَدَ ۙ‏'),
('s90a4', 4, 90, 'لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِى كَبَدٍ', 'لَقَدۡ خَلَقۡنَا الۡاِنۡسَانَ فِىۡ كَبَدٍؕ‏'),
('s90a5', 5, 90, 'أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌ', 'اَيَحۡسَبُ اَنۡ لَّنۡ يَّقۡدِرَ عَلَيۡهِ اَحَدٌ​ ۘ‏'),
('s90a6', 6, 90, 'يَقُولُ أَهْلَكْتُ مَالًا لُّبَدًا', 'يَقُوۡلُ اَهۡلَكۡتُ مَالًا لُّبَدًا ؕ‏'),
('s90a7', 7, 90, 'أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ', 'اَيَحۡسَبُ اَنۡ لَّمۡ يَرَهٗۤ اَحَدٌ ؕ‏'),
('s90a8', 8, 90, 'أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ', 'اَلَمۡ نَجۡعَلۡ لَّهٗ عَيۡنَيۡنِۙ‏'),
('s90a9', 9, 90, 'وَلِسَانًا وَشَفَتَيْنِ', 'وَلِسَانًا وَّشَفَتَيۡنِۙ‏'),
('s90a10', 10, 90, 'وَهَدَيْنَـٰهُ ٱلنَّجْدَيْنِ', 'وَهَدَيۡنٰهُ النَّجۡدَيۡنِ​ۚ‏'),
('s90a11', 11, 90, 'فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ', 'فَلَا اقۡتَحَمَ الۡعَقَبَةَ ۖ‏'),
('s90a12', 12, 90, 'وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ', 'وَمَاۤ اَدۡرٰٮكَ مَا الۡعَقَبَةُ ؕ‏'),
('s90a13', 13, 90, 'فَكُّ رَقَبَةٍ', 'فَكُّ رَقَبَةٍ ۙ‏'),
('s90a14', 14, 90, 'أَوْ إِطْعَـٰمٌ فِى يَوْمٍ ذِى مَسْغَبَةٍ', 'اَوۡ اِطۡعٰمٌ فِىۡ يَوۡمٍ ذِىۡ مَسۡغَبَةٍ ۙ‏'),
('s90a15', 15, 90, 'يَتِيمًا ذَا مَقْرَبَةٍ', 'يَّتِيۡمًا ذَا مَقۡرَبَةٍ ۙ‏'),
('s90a16', 16, 90, 'أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ', 'اَوۡ مِسۡكِيۡنًا ذَا مَتۡرَبَةٍ ؕ‏'),
('s90a17', 17, 90, 'ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ', 'ثُمَّ كَانَ مِنَ الَّذِيۡنَ اٰمَنُوۡا وَتَوَاصَوۡا بِالصَّبۡرِ وَتَوَاصَوۡا بِالۡمَرۡحَمَةِ ؕ‏'),
('s90a18', 18, 90, 'أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْمَيْمَنَةِ', 'اُولٰٓٮِٕكَ اَصۡحٰبُ الۡمَيۡمَنَةِ ؕ‏'),
('s90a19', 19, 90, 'وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِنَا هُمْ أَصْحَـٰبُ ٱلْمَشْـَٔمَةِ', 'وَالَّذِيۡنَ كَفَرُوۡا بِاٰيٰتِنَا هُمۡ اَصۡحٰبُ الۡمَشۡـَٔـمَةِ ؕ‏'),
('s90a20', 20, 90, 'عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌۢ', 'عَلَيۡهِمۡ نَارٌ مُّؤۡصَدَةٌ‏'),
('s91a1', 1, 91, ' وَٱلشَّمْسِ وَضُحَىٰهَا', 'وَالشَّمۡسِ وَضُحٰٮهَا  ۙ‏'),
('s91a2', 2, 91, 'وَٱلْقَمَرِ إِذَا تَلَىٰهَا', 'وَالۡقَمَرِ اِذَا تَلٰٮهَا  ۙ‏'),
('s91a3', 3, 91, 'وَٱلنَّهَارِ إِذَا جَلَّىٰهَا', 'وَالنَّهَارِ اِذَا جَلّٰٮهَا ۙ‏'),
('s91a4', 4, 91, 'وَٱلَّيْلِ إِذَا يَغْشَىٰهَا', 'وَالَّيۡلِ اِذَا يَغۡشٰٮهَا ۙ‏'),
('s91a5', 5, 91, 'وَٱلسَّمَآءِ وَمَا بَنَىٰهَا', 'وَالسَّمَآءِ وَمَا بَنٰٮهَا ۙ‏'),
('s91a6', 6, 91, 'وَٱلْأَرْضِ وَمَا طَحَىٰهَا', 'وَالۡاَرۡضِ وَمَا طَحٰٮهَا ۙ‏'),
('s91a7', 7, 91, 'وَنَفْسٍ وَمَا سَوَّىٰهَا', 'وَنَفۡسٍ وَّمَا سَوّٰٮهَا ۙ‏'),
('s91a8', 8, 91, 'فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا', 'فَاَلۡهَمَهَا فُجُوۡرَهَا وَتَقۡوٰٮهَا ۙ‏'),
('s91a9', 9, 91, 'قَدْ أَفْلَحَ مَن زَكَّىٰهَا', 'قَدۡ اَفۡلَحَ مَنۡ زَكّٰٮهَا ۙ‏'),
('s91a10', 10, 91, 'وَقَدْ خَابَ مَن دَسَّىٰهَا', 'وَقَدۡ خَابَ مَنۡ دَسّٰٮهَا ؕ‏'),
('s91a11', 11, 91, 'كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ', 'كَذَّبَتۡ ثَمُوۡدُ بِطَغۡوٰٮهَآ  ۙ‏'),
('s91a12', 12, 91, 'إِذِ ٱنۢبَعَثَ أَشْقَىٰهَا', 'اِذِ انۡۢبَعَثَ اَشۡقٰٮهَا  ۙ‏'),
('s91a13', 13, 91, 'فَقَالَ لَهُمْ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقْيَـٰهَا', 'فَقَالَ لَهُمۡ رَسُوۡلُ اللّٰهِ نَاقَةَ اللّٰهِ وَسُقۡيٰهَا ؕ‏'),
('s91a14', 14, 91, 'فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّىٰهَا', 'فَكَذَّبُوۡهُ فَعَقَرُوۡهَا   ۙفَدَمۡدَمَ عَلَيۡهِمۡ رَبُّهُمۡ بِذَنۡۢبِهِمۡ فَسَوّٰٮهَا  ۙ‏'),
('s91a15', 15, 91, 'وَلَا يَخَافُ عُقْبَـٰهَا', 'وَلَا يَخَافُ عُقۡبٰهَا‏'),
('s92a1', 1, 92, ' وَٱلَّيْلِ إِذَا يَغْشَىٰ', 'وَالَّيۡلِ اِذَا يَغۡشٰىۙ‏'),
('s92a2', 2, 92, 'وَٱلنَّهَارِ إِذَا تَجَلَّىٰ', 'وَالنَّهَارِ اِذَا تَجَلّٰىۙ‏'),
('s92a3', 3, 92, 'وَمَا خَلَقَ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ', 'وَمَا خَلَقَ الذَّكَرَ وَالۡاُنۡثٰٓىۙ‏'),
('s92a4', 4, 92, 'إِنَّ سَعْيَكُمْ لَشَتَّىٰ', 'اِنَّ سَعۡيَكُمۡ لَشَتّٰىؕ‏'),
('s92a5', 5, 92, 'فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ', 'فَاَمَّا مَنۡ اَعۡطٰى وَاتَّقٰىۙ‏'),
('s92a6', 6, 92, 'وَصَدَّقَ بِٱلْحُسْنَىٰ', 'وَصَدَّقَ بِالۡحُسۡنٰىۙ‏'),
('s92a7', 7, 92, 'فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ', 'فَسَنُيَسِّرُهٗ لِلۡيُسۡرٰىؕ‏'),
('s92a8', 8, 92, 'وَأَمَّا مَنۢ بَخِلَ وَٱسْتَغْنَىٰ', 'وَاَمَّا مَنۡۢ بَخِلَ وَاسۡتَغۡنٰىۙ‏'),
('s92a9', 9, 92, 'وَكَذَّبَ بِٱلْحُسْنَىٰ', 'وَكَذَّبَ بِالۡحُسۡنٰىۙ‏'),
('s92a10', 10, 92, 'فَسَنُيَسِّرُهُۥ لِلْعُسْرَىٰ', 'فَسَنُيَسِّرُهٗ لِلۡعُسۡرٰىؕ‏'),
('s92a11', 11, 92, 'وَمَا يُغْنِى عَنْهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ', 'وَمَا يُغۡنِىۡ عَنۡهُ مَالُهٗۤ اِذَا تَرَدّٰىؕ‏'),
('s92a12', 12, 92, 'إِنَّ عَلَيْنَا لَلْهُدَىٰ', 'اِنَّ عَلَيۡنَا لَـلۡهُدٰىۖ‏'),
('s92a13', 13, 92, 'وَإِنَّ لَنَا لَلْـَٔاخِرَةَ وَٱلْأُولَىٰ', 'وَاِنَّ لَـنَا لَـلۡاٰخِرَةَ وَالۡاُوۡلٰى‏'),
('s92a14', 14, 92, 'فَأَنذَرْتُكُمْ نَارًا تَلَظَّىٰ', 'فَاَنۡذَرۡتُكُمۡ نَارًا تَلَظّٰى​ۚ‏'),
('s92a15', 15, 92, 'لَا يَصْلَىٰهَآ إِلَّا ٱلْأَشْقَى', 'لَا يَصۡلٰٮهَاۤ اِلَّا الۡاَشۡقَىۙ‏'),
('s92a16', 16, 92, 'ٱلَّذِى كَذَّبَ وَتَوَلَّىٰ', 'الَّذِىۡ كَذَّبَ وَتَوَلّٰىؕ‏'),
('s92a17', 17, 92, 'وَسَيُجَنَّبُهَا ٱلْأَتْقَى', 'وَسَيُجَنَّبُهَا الۡاَتۡقَىۙ‏'),
('s92a18', 18, 92, 'ٱلَّذِى يُؤْتِى مَالَهُۥ يَتَزَكَّىٰ', 'الَّذِىۡ يُؤۡتِىۡ مَالَهٗ يَتَزَكّٰى​ۚ‏'),
('s92a19', 19, 92, 'وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍ تُجْزَىٰٓ', 'وَمَا لِاَحَدٍ عِنۡدَهٗ مِنۡ نِّعۡمَةٍ تُجۡزٰٓىۙ‏'),
('s92a20', 20, 92, 'إِلَّا ٱبْتِغَآءَ وَجْهِ رَبِّهِ ٱلْأَعْلَىٰ', 'اِلَّا ابۡتِغَآءَ وَجۡهِ رَبِّهِ الۡاَعۡلٰى​ۚ‏'),
('s92a21', 21, 92, 'وَلَسَوْفَ يَرْضَىٰ', 'وَلَسَوۡفَ يَرۡضٰى‏'),
('s93a1', 1, 93, ' وَٱلضُّحَىٰ', 'وَالضُّحٰىۙ‏'),
('s93a2', 2, 93, 'وَٱلَّيْلِ إِذَا سَجَىٰ', 'وَالَّيۡلِ اِذَا سَجٰىۙ‏'),
('s93a3', 3, 93, 'مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ', 'مَا وَدَّعَكَ رَبُّكَ وَمَا قَلٰىؕ‏'),
('s93a4', 4, 93, 'وَلَلْـَٔاخِرَةُ خَيْرٌ لَّكَ مِنَ ٱلْأُولَىٰ', 'وَلَـلۡاٰخِرَةُ خَيۡرٌ لَّكَ مِنَ الۡاُوۡلٰىؕ‏'),
('s93a5', 5, 93, 'وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ', 'وَلَسَوۡفَ يُعۡطِيۡكَ رَبُّكَ فَتَرۡضٰىؕ‏'),
('s93a6', 6, 93, 'أَلَمْ يَجِدْكَ يَتِيمًا فَـَٔاوَىٰ', 'اَلَمۡ يَجِدۡكَ يَتِيۡمًا فَاٰوٰى‏'),
('s93a7', 7, 93, 'وَوَجَدَكَ ضَآلًّا فَهَدَىٰ', 'وَوَجَدَكَ ضَآ لًّا فَهَدٰى‏'),
('s93a8', 8, 93, 'وَوَجَدَكَ عَآئِلًا فَأَغْنَىٰ', 'وَوَجَدَكَ عَآٮِٕلًا فَاَغۡنٰىؕ‏'),
('s93a9', 9, 93, 'فَأَمَّا ٱلْيَتِيمَ فَلَا تَقْهَرْ', 'فَاَمَّا الۡيَتِيۡمَ فَلَا تَقۡهَرۡؕ‏'),
('s93a10', 10, 93, 'وَأَمَّا ٱلسَّآئِلَ فَلَا تَنْهَرْ', 'وَاَمَّا السَّآٮِٕلَ فَلَا تَنۡهَرۡؕ‏'),
('s93a11', 11, 93, 'وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ', 'وَاَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ‏'),
('s94a1', 1, 94, ' أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ', 'اَلَمۡ نَشۡرَحۡ لَـكَ صَدۡرَكَۙ‏'),
('s94a2', 2, 94, 'وَوَضَعْنَا عَنكَ وِزْرَكَ', 'وَوَضَعۡنَا عَنۡكَ وِزۡرَكَۙ‏'),
('s94a3', 3, 94, 'ٱلَّذِىٓ أَنقَضَ ظَهْرَكَ', 'الَّذِىۡۤ اَنۡقَضَ ظَهۡرَكَۙ‏'),
('s94a4', 4, 94, 'وَرَفَعْنَا لَكَ ذِكْرَكَ', 'وَرَفَعۡنَا لَـكَ ذِكۡرَكَؕ‏'),
('s94a5', 5, 94, 'فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا', 'فَاِنَّ مَعَ الۡعُسۡرِ يُسۡرًا ۙ‏'),
('s94a6', 6, 94, 'إِنَّ مَعَ ٱلْعُسْرِ يُسْرًا', 'اِنَّ مَعَ الۡعُسۡرِ يُسۡرًا ؕ‏'),
('s94a7', 7, 94, 'فَإِذَا فَرَغْتَ فَٱنصَبْ', 'فَاِذَا فَرَغۡتَ فَانۡصَبۡۙ‏'),
('s94a8', 8, 94, 'وَإِلَىٰ رَبِّكَ فَٱرْغَب', 'وَاِلٰى رَبِّكَ فَارۡغَب‏'),
('s95a1', 1, 95, 'وَٱلتِّينِ وَٱلزَّيْتُونِ', 'وَالتِّيۡنِ وَالزَّيۡتُوۡنِۙ‏'),
('s95a2', 2, 95, 'وَطُورِ سِينِينَ', 'وَطُوۡرِ سِيۡنِيۡنَۙ‏'),
('s95a3', 3, 95, 'وَهَـٰذَا ٱلْبَلَدِ ٱلْأَمِينِ', 'وَهٰذَا الۡبَلَدِ الۡاَمِيۡنِۙ‏'),
('s95a4', 4, 95, 'لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍ', 'لَقَدۡ خَلَقۡنَا الۡاِنۡسَانَ فِىۡۤ اَحۡسَنِ تَقۡوِيۡمٍ‏'),
('s95a5', 5, 95, 'ثُمَّ رَدَدْنَـٰهُ أَسْفَلَ سَـٰفِلِينَ', 'ثُمَّ رَدَدۡنٰهُ اَسۡفَلَ سَافِلِيۡنَۙ‏'),
('s95a6', 6, 95, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ', 'اِلَّا الَّذِيۡنَ اٰمَنُوۡا وَعَمِلُوا الصّٰلِحٰتِ فَلَهُمۡ اَجۡرٌ غَيۡرُ مَمۡنُوۡنٍؕ‏'),
('s95a7', 7, 95, 'فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ', 'فَمَا يُكَذِّبُكَ بَعۡدُ بِالدِّيۡنِ‏'),
('s95a8', 8, 95, 'أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَـٰكِمِينَ', 'اَلَيۡسَ اللّٰهُ بِاَحۡكَمِ الۡحٰكِمِيۡنَ‏'),
('s96a1', 1, 96, ' ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ', 'اِقۡرَاۡ بِاسۡمِ رَبِّكَ الَّذِىۡ خَلَقَ​ۚ‏'),
('s96a2', 2, 96, 'خَلَقَ ٱلْإِنسَـٰنَ مِنْ عَلَقٍ', 'خَلَقَ الۡاِنۡسَانَ مِنۡ عَلَقٍ​ۚ‏'),
('s96a3', 3, 96, 'ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ', 'اِقۡرَاۡ وَرَبُّكَ الۡاَكۡرَمُۙ‏'),
('s96a4', 4, 96, 'ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ', 'الَّذِىۡ عَلَّمَ بِالۡقَلَمِۙ‏'),
('s96a5', 5, 96, 'عَلَّمَ ٱلْإِنسَـٰنَ مَا لَمْ يَعْلَمْ', 'عَلَّمَ الۡاِنۡسَانَ مَا لَمۡ يَعۡلَمۡؕ‏'),
('s96a6', 6, 96, 'كَلَّآ إِنَّ ٱلْإِنسَـٰنَ لَيَطْغَىٰٓ', 'كَلَّاۤ اِنَّ الۡاِنۡسَانَ لَيَطۡغٰٓىۙ‏'),
('s96a7', 7, 96, 'أَن رَّءَاهُ ٱسْتَغْنَىٰٓ', 'اَنۡ رَّاٰهُ اسۡتَغۡنٰىؕ‏'),
('s96a8', 8, 96, 'إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ', 'اِنَّ اِلٰى رَبِّكَ الرُّجۡعٰىؕ‏'),
('s96a9', 9, 96, 'أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ', 'اَرَءَيۡتَ الَّذِىۡ يَنۡهٰىؕ‏'),
('s96a10', 10, 96, 'عَبْدًا إِذَا صَلَّىٰٓ', 'عَبۡدًا اِذَا صَلّٰىؕ‏'),
('s96a11', 11, 96, 'أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ', 'اَرَءَيۡتَ اِنۡ كَانَ عَلَى الۡهُدٰٓىۙ‏'),
('s96a12', 12, 96, 'أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ', 'اَوۡ اَمَرَ بِالتَّقۡوٰىۙ‏'),
('s96a13', 13, 96, 'أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ', 'اَرَءَيۡتَ اِنۡ كَذَّبَ وَتَوَلّٰىؕ‏'),
('s96a14', 14, 96, 'أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ', 'اَلَمۡ يَعۡلَمۡ بِاَنَّ اللّٰهَ يَرٰىؕ‏'),
('s96a15', 15, 96, 'كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ', 'كَلَّا لَٮِٕنۡ لَّمۡ يَنۡتَهِ  ۙ لَنَسۡفَعًۢا بِالنَّاصِيَةِۙ‏'),
('s96a16', 16, 96, 'نَاصِيَةٍ كَـٰذِبَةٍ خَاطِئَةٍ', 'نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ​ ۚ‏'),
('s96a17', 17, 96, 'فَلْيَدْعُ نَادِيَهُۥ', 'فَلۡيَدۡعُ نَادِيَهٗ ۙ‏'),
('s96a18', 18, 96, 'سَنَدْعُ ٱلزَّبَانِيَةَ', 'سَنَدۡعُ الزَّبَانِيَةَ ۙ‏'),
('s96a19', 19, 96, 'كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب ۩', 'كَلَّا ؕ لَا تُطِعۡهُ وَاسۡجُدۡ وَاقۡتَرِبْ۩‏'),
('s97a1', 1, 97, 'إِنَّآ أَنزَلْنَـٰهُ فِى لَيْلَةِ ٱلْقَدْرِ', 'اِنَّاۤ اَنۡزَلۡنٰهُ فِىۡ لَيۡلَةِ الۡقَدۡرِ ۖ ۚ‏'),
('s97a2', 2, 97, 'وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ', 'وَمَاۤ اَدۡرٰٮكَ مَا لَيۡلَةُ الۡقَدۡرِؕ‏'),
('s97a3', 3, 97, 'لَيْلَةُ ٱلْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ', 'لَيۡلَةُ الۡقَدۡرِ  ۙ خَيۡرٌ مِّنۡ اَلۡفِ شَهۡرٍؕ‏'),
('s97a4', 4, 97, 'تَنَزَّلُ ٱلْمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ', 'تَنَزَّلُ الۡمَلٰٓٮِٕكَةُ وَالرُّوۡحُ فِيۡهَا بِاِذۡنِ رَبِّهِمۡ​ۚ مِّنۡ كُلِّ اَمۡرٍ ۛۙ‏'),
('s97a5', 5, 97, 'سَلَـٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ', 'سَلٰمٌ   ۛهِىَ حَتّٰى مَطۡلَعِ الۡفَجۡرِ‏'),
('s98a1', 1, 98, ' لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ', 'لَمۡ يَكُنِ الَّذِيۡنَ كَفَرُوۡا مِنۡ اَهۡلِ الۡكِتٰبِ وَالۡمُشۡرِكِيۡنَ مُنۡفَكِّيۡنَ حَتّٰى تَاۡتِيَهُمُ الۡبَيِّنَةُ ۙ‏'),
('s98a2', 2, 98, 'رَسُولٌ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًا مُّطَهَّرَةً', 'رَسُوۡلٌ مِّنَ اللّٰهِ يَتۡلُوۡا صُحُفًا مُّطَهَّرَةً ۙ‏'),
('s98a3', 3, 98, 'فِيهَا كُتُبٌ قَيِّمَةٌ', 'فِيۡهَا كُتُبٌ قَيِّمَةٌ ؕ‏'),
('s98a4', 4, 98, 'وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ', 'وَمَا تَفَرَّقَ الَّذِيۡنَ اُوۡتُوا الۡكِتٰبَ اِلَّا مِنۡۢ بَعۡدِ مَا جَآءَتۡهُمُ الۡبَيِّنَةُ ؕ‏'),
('s98a5', 5, 98, 'وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ', 'وَمَاۤ اُمِرُوۡۤا اِلَّا لِيَعۡبُدُوا اللّٰهَ مُخۡلِصِيۡنَ لَـهُ الدِّيۡنَ  ۙ حُنَفَآءَ وَيُقِيۡمُوا الصَّلٰوةَ وَيُؤۡتُوا الزَّكٰوةَ​ وَذٰلِكَ دِيۡنُ الۡقَيِّمَةِ ؕ‏'),
('s98a6', 6, 98, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ ۚ أُو۟لَـٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ', 'اِنَّ الَّذِيۡنَ كَفَرُوۡا مِنۡ اَهۡلِ الۡكِتٰبِ وَ الۡمُشۡرِكِيۡنَ فِىۡ نَارِ جَهَنَّمَ خٰلِدِيۡنَ فِيۡهَا ​ؕ اُولٰٓٮِٕكَ هُمۡ شَرُّ الۡبَرِيَّةِ ؕ‏'),
('s98a7', 7, 98, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ', 'اِنَّ الَّذِيۡنَ اٰمَنُوۡا وَعَمِلُوا الصّٰلِحٰتِۙ اُولٰٓٮِٕكَ هُمۡ خَيۡرُ الۡبَرِيَّةِ ؕ‏'),
('s98a8', 8, 98, 'جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّـٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ', 'جَزَآؤُهُمۡ عِنۡدَ رَبِّهِمۡ جَنّٰتُ عَدۡنٍ تَجۡرِىۡ مِنۡ تَحۡتِهَا الۡاَنۡهٰرُ خٰلِدِيۡنَ فِيۡهَاۤ اَبَدًا ​ؕ رَضِىَ اللّٰهُ عَنۡهُمۡ وَرَضُوۡا عَنۡهُ ​ؕ ذٰلِكَ لِمَنۡ خَشِىَ رَبَّهٗ‏'),
('s99a1', 1, 99, ' إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا', 'اِذَا زُلۡزِلَتِ الۡاَرۡضُ زِلۡزَالَهَا ۙ‏'),
('s99a2', 2, 99, 'وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا', 'وَاَخۡرَجَتِ الۡاَرۡضُ اَثۡقَالَهَا ۙ‏'),
('s99a3', 3, 99, 'وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا', 'وَقَالَ الۡاِنۡسَانُ مَا لَهَا​ ۚ‏'),
('s99a4', 4, 99, 'يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا', 'يَوۡمَٮِٕذٍ تُحَدِّثُ اَخۡبَارَهَا ۙ‏'),
('s99a5', 5, 99, 'بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا', 'بِاَنَّ رَبَّكَ اَوۡحٰى لَهَا ؕ‏'),
('s99a6', 6, 99, 'يَوْمَئِذٍ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًا لِّيُرَوْا۟ أَعْمَـٰلَهُمْ', 'يَوۡمَٮِٕذٍ يَّصۡدُرُ النَّاسُ اَشۡتَاتًا  ۙ لِّيُرَوۡا اَعۡمَالَهُمۡؕ‏ ﻿﻿'),
('s99a7', 7, 99, 'فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ', 'فَمَنۡ يَّعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرًا يَّرَهٗ ؕ‏'),
('s99a8', 8, 99, 'وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ', 'وَمَنۡ يَّعۡمَلۡ مِثۡقَالَ ذَرَّةٍ شَرًّا يَّرَهٗ‏'),
('s100a1', 1, 100, ' وَٱلْعَـٰدِيَـٰتِ ضَبْحًا', 'وَالۡعٰدِيٰتِ ضَبۡحًا ۙ‏'),
('s100a2', 2, 100, 'فَٱلْمُورِيَـٰتِ قَدْحًا', 'فَالۡمُوۡرِيٰتِ قَدۡحًا ۙ‏'),
('s100a3', 3, 100, 'فَٱلْمُغِيرَٰتِ صُبْحًا', 'فَالۡمُغِيۡرٰتِ صُبۡحًا ۙ‏'),
('s100a4', 4, 100, 'فَأَثَرْنَ بِهِۦ نَقْعًا', 'فَاَثَرۡنَ بِهٖ نَقۡعًا ۙ‏'),
('s100a5', 5, 100, 'فَوَسَطْنَ بِهِۦ جَمْعًا', 'فَوَسَطۡنَ بِهٖ جَمۡعًا ۙ‏'),
('s100a6', 6, 100, 'إِنَّ ٱلْإِنسَـٰنَ لِرَبِّهِۦ لَكَنُودٌ', 'اِنَّ الۡاِنۡسَانَ لِرَبِّهٖ لَـكَنُوۡدٌ ۚ‏'),
('s100a7', 7, 100, 'وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌ', 'وَاِنَّهٗ عَلٰى ذٰلِكَ لَشَهِيۡدٌ ۚ‏'),
('s100a8', 8, 100, 'وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ', 'وَاِنَّهٗ لِحُبِّ الۡخَيۡرِ لَشَدِيۡدٌ ؕ‏'),
('s100a9', 9, 100, '۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ', 'اَفَلَا يَعۡلَمُ اِذَا بُعۡثِرَ مَا فِى الۡقُبُوۡرِۙ‏'),
('s100a10', 10, 100, 'وَحُصِّلَ مَا فِى ٱلصُّدُورِ', 'وَحُصِّلَ مَا فِى الصُّدُوۡرِۙ‏'),
('s100a11', 11, 100, 'إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍ لَّخَبِيرٌۢ', 'اِنَّ رَبَّهُمۡ بِهِمۡ يَوۡمَٮِٕذٍ لَّخَبِيۡرٌ‏'),
('s101a1', 1, 101, ' ٱلْقَارِعَةُ', 'اَلۡقَارِعَةُ ۙ‏'),
('s101a2', 2, 101, 'مَا ٱلْقَارِعَةُ', 'مَا الۡقَارِعَةُ​ ۚ‏'),
('s101a3', 3, 101, 'وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ', 'وَمَاۤ اَدۡرٰٮكَ مَا الۡقَارِعَةُ ؕ‏'),
('s101a4', 4, 101, 'يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ', 'يَوۡمَ يَكُوۡنُ النَّاسُ كَالۡفَرَاشِ الۡمَبۡثُوۡثِۙ‏'),
('s101a5', 5, 101, 'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ', 'وَتَكُوۡنُ الۡجِبَالُ كَالۡعِهۡنِ الۡمَنۡفُوۡشِؕ‏'),
('s101a6', 6, 101, 'فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ', 'فَاَمَّا مَنۡ ثَقُلَتۡ مَوَازِيۡنُهٗ ۙ‏'),
('s101a7', 7, 101, 'فَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ', 'فَهُوَ فِىۡ عِيۡشَةٍ رَّاضِيَةٍ ؕ‏'),
('s101a8', 8, 101, 'وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ', 'وَاَمَّا مَنۡ خَفَّتۡ مَوَازِيۡنُهٗ ۙ‏'),
('s101a9', 9, 101, 'فَأُمُّهُۥ هَاوِيَةٌ', 'فَاُمُّهٗ هَاوِيَةٌ ؕ‏'),
('s101a10', 10, 101, 'وَمَآ أَدْرَىٰكَ مَا هِيَهْ', 'وَمَاۤ اَدۡرٰٮكَ مَا هِيَهۡ ؕ‏'),
('s101a11', 11, 101, 'نَارٌ حَامِيَةٌۢ', 'نَارٌ حَامِيَةٌ‏'),
('s102a1', 1, 102, ' أَلْهَىٰكُمُ ٱلتَّكَاثُرُ', 'اَلۡهٰٮكُمُ التَّكَاثُرُۙ‏'),
('s102a2', 2, 102, 'حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ', 'حَتّٰى زُرۡتُمُ الۡمَقَابِرَؕ‏'),
('s102a3', 3, 102, 'كَلَّا سَوْفَ تَعْلَمُونَ', 'كَلَّا سَوۡفَ تَعۡلَمُوۡنَۙ‏'),
('s102a4', 4, 102, 'ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ', 'ثُمَّ كَلَّا سَوۡفَ تَعۡلَمُوۡنَؕ‏'),
('s102a5', 5, 102, 'كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ', 'كَلَّا لَوۡ تَعۡلَمُوۡنَ عِلۡمَ الۡيَقِيۡنِؕ‏'),
('s102a6', 6, 102, 'لَتَرَوُنَّ ٱلْجَحِيمَ', 'لَتَرَوُنَّ الۡجَحِيۡمَۙ‏'),
('s102a7', 7, 102, 'ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ', 'ثُمَّ لَتَرَوُنَّهَا عَيۡنَ الۡيَقِيۡنِۙ‏'),
('s102a8', 8, 102, 'ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ', 'ثُمَّ لَـتُسۡـَٔـلُنَّ يَوۡمَٮِٕذٍ عَنِ النَّعِيۡمِ‏'),
('s103a1', 1, 103, ' وَٱلْعَصْرِ', 'وَالۡعَصۡرِۙ‏'),
('s103a2', 2, 103, 'إِنَّ ٱلْإِنسَـٰنَ لَفِى خُسْرٍ', 'اِنَّ الۡاِنۡسَانَ لَفِىۡ خُسۡرٍۙ‏'),
('s103a3', 3, 103, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ', 'اِلَّا الَّذِيۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ وَتَوَاصَوۡا بِالۡحَقِّ   ۙ وَتَوَاصَوۡا بِالصَّبۡرِ‏'),
('s104a1', 1, 104, ' وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ', 'وَيۡلٌ لِّـكُلِّ هُمَزَةٍ لُّمَزَةِ ۙ‏'),
('s104a2', 2, 104, 'ٱلَّذِى جَمَعَ مَالًا وَعَدَّدَهُۥ', 'اۨلَّذِىۡ جَمَعَ مَالًا وَّعَدَّدَهٗ ۙ‏'),
('s104a3', 3, 104, 'يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ', 'يَحۡسَبُ اَنَّ مَالَهٗۤ اَخۡلَدَهٗ​ ۚ‏'),
('s104a4', 4, 104, 'كَلَّا ۖ لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ', 'كَلَّا​ لَيُنۡۢبَذَنَّ فِى الۡحُطَمَةِ  ۖ‏'),
('s104a5', 5, 104, 'وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ', 'وَمَاۤ اَدۡرٰٮكَ مَا الۡحُطَمَةُ ؕ‏'),
('s104a6', 6, 104, 'نَارُ ٱللَّهِ ٱلْمُوقَدَةُ', 'نَارُ اللّٰهِ الۡمُوۡقَدَةُ ۙ‏'),
('s104a7', 7, 104, 'ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ', 'الَّتِىۡ تَطَّلِعُ عَلَى الۡاَفۡـــِٕدَةِ ؕ‏'),
('s104a8', 8, 104, 'إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ', 'اِنَّهَا عَلَيۡهِمۡ مُّؤۡصَدَةٌ ۙ‏'),
('s104a9', 9, 104, 'فِى عَمَدٍ مُّمَدَّدَةٍۭ', 'فِىۡ عَمَدٍ مُّمَدَّدَةٍ‏'),
('s105a1', 1, 105, ' أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَـٰبِ ٱلْفِيلِ', 'اَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِاَصۡحٰبِ الۡفِيۡلِؕ‏'),
('s105a2', 2, 105, 'أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍ', 'اَلَمۡ يَجۡعَلۡ كَيۡدَهُمۡ فِىۡ تَضۡلِيۡلٍۙ‏'),
('s105a3', 3, 105, 'وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ', 'وَّاَرۡسَلَ عَلَيۡهِمۡ طَيۡرًا اَبَابِيۡلَۙ‏'),
('s105a4', 4, 105, 'تَرْمِيهِم بِحِجَارَةٍ مِّن سِجِّيلٍ', 'تَرۡمِيۡهِمۡ بِحِجَارَةٍ مِّنۡ سِجِّيۡلٍۙ‏'),
('s105a5', 5, 105, 'فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُولٍۭ', 'فَجَعَلَهُمۡ كَعَصۡفٍ مَّاۡكُوۡلٍ‏'),
('s106a1', 1, 106, ' لِإِيلَـٰفِ قُرَيْشٍ', 'لِاِيۡلٰفِ قُرَيۡشٍۙ‏'),
('s106a2', 2, 106, 'إِۦلَـٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ', 'اٖلٰفِهِمۡ رِحۡلَةَ الشِّتَآءِ وَالصَّيۡفِ​ۚ‏'),
('s106a3', 3, 106, 'فَلْيَعْبُدُوا۟ رَبَّ هَـٰذَا ٱلْبَيْتِ', 'فَلۡيَـعۡبُدُوۡا رَبَّ هٰذَا الۡبَيۡتِۙ‏'),
('s106a4', 4, 106, 'ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍ وَءَامَنَهُم مِّنْ خَوْفٍۭ', 'الَّذِىۡۤ اَطۡعَمَهُمۡ مِّنۡ جُوۡعٍ   ۙ وَّاٰمَنَهُمۡ مِّنۡ خَوۡفٍ‏'),
('s107a1', 1, 107, ' أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ', 'اَرَءَيۡتَ الَّذِىۡ يُكَذِّبُ بِالدِّيۡنِؕ‏'),
('s107a2', 2, 107, 'فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ', 'فَذٰلِكَ الَّذِىۡ يَدُعُّ الۡيَتِيۡمَۙ‏'),
('s107a3', 3, 107, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 'وَ لَا يَحُضُّ عَلٰى طَعَامِ الۡمِسۡكِيۡنِؕ‏'),
('s107a4', 4, 107, 'فَوَيْلٌ لِّلْمُصَلِّينَ', 'فَوَيۡلٌ لِّلۡمُصَلِّيۡنَۙ‏'),
('s107a5', 5, 107, 'ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ', 'الَّذِيۡنَ هُمۡ عَنۡ صَلَاتِهِمۡ سَاهُوۡنَۙ‏'),
('s107a6', 6, 107, 'ٱلَّذِينَ هُمْ يُرَآءُونَ', 'الَّذِيۡنَ هُمۡ يُرَآءُوۡنَۙ‏'),
('s107a7', 7, 107, 'وَيَمْنَعُونَ ٱلْمَاعُونَ', 'وَيَمۡنَعُوۡنَ الۡمَاعُوۡنَ‏'),
('s108a1', 1, 108, ' إِنَّآ أَعْطَيْنَـٰكَ ٱلْكَوْثَرَ', 'اِنَّاۤ اَعۡطَيۡنٰكَ الۡكَوۡثَرَؕ‏'),
('s108a2', 2, 108, 'فَصَلِّ لِرَبِّكَ وَٱنْحَرْ', 'فَصَلِّ لِرَبِّكَ وَانۡحَرۡ ؕ‏'),
('s108a3', 3, 108, 'إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ', 'اِنَّ شَانِئَكَ هُوَ الۡاَبۡتَرُ‏'),
('s109a1', 1, 109, ' قُلْ يَـٰٓأَيُّهَا ٱلْكَـٰفِرُونَ', 'قُلۡ يٰۤاَيُّهَا الۡكٰفِرُوۡنَۙ‏'),
('s109a2', 2, 109, 'لَآ أَعْبُدُ مَا تَعْبُدُونَ', 'لَاۤ اَعۡبُدُ مَا تَعۡبُدُوۡنَۙ‏'),
('s109a3', 3, 109, 'وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ', 'وَلَاۤ اَنۡـتُمۡ عٰبِدُوۡنَ مَاۤ اَعۡبُدُ​ ۚ‏'),
('s109a4', 4, 109, 'وَلَآ أَنَا۠ عَابِدٌ مَّا عَبَدتُّمْ', 'وَلَاۤ اَنَا عَابِدٌ مَّا عَبَدۡتُّمۡۙ‏'),
('s109a5', 5, 109, 'وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ', 'وَ لَاۤ اَنۡـتُمۡ عٰبِدُوۡنَ مَاۤ اَعۡبُدُ ؕ‏'),
('s109a6', 6, 109, 'لَكُمْ دِينُكُمْ وَلِىَ دِينِ', 'لَـكُمۡ دِيۡنُكُمۡ وَلِىَ دِيۡنِ‏'),
('s110a1', 1, 110, ' إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ', 'اِذَا جَآءَ نَصۡرُ اللّٰهِ وَالۡفَتۡحُۙ‏'),
('s110a2', 2, 110, 'وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًا', 'وَرَاَيۡتَ النَّاسَ يَدۡخُلُوۡنَ فِىۡ دِيۡنِ اللّٰهِ اَفۡوَاجًا ۙ‏'),
('s110a3', 3, 110, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا', 'فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَاسۡتَغۡفِرۡهُ​ ؕ اِنَّهٗ كَانَ تَوَّابًا‏'),
('s111a1', 1, 111, ' تَبَّتْ يَدَآ أَبِى لَهَبٍ وَتَبَّ', 'تَبَّتۡ يَدَاۤ اَبِىۡ لَهَبٍ وَّتَبَّؕ‏'),
('s111a2', 2, 111, 'مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ', 'مَاۤ اَغۡنٰى عَنۡهُ مَالُهٗ وَمَا كَسَبَؕ‏'),
('s111a3', 3, 111, 'سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ', 'سَيَصۡلٰى نَارًا ذَاتَ لَهَبٍ ۖۚ‏'),
('s111a4', 4, 111, 'وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ', 'وَّامۡرَاَ تُهٗ ؕ حَمَّالَةَ الۡحَطَبِ​ۚ‏'),
('s111a5', 5, 111, 'فِى جِيدِهَا حَبْلٌ مِّن مَّسَدٍۭ', 'فِىۡ جِيۡدِهَا حَبۡلٌ مِّنۡ مَّسَدٍ‏'),
('s112a1', 1, 112, ' قُلْ هُوَ ٱللَّهُ أَحَدٌ', 'قُلۡ هُوَ اللّٰهُ اَحَدٌ​ ۚ‏'),
('s112a2', 2, 112, 'ٱللَّهُ ٱلصَّمَدُ', 'اَللّٰهُ الصَّمَدُ​ ۚ‏'),
('s112a3', 3, 112, 'لَمْ يَلِدْ وَلَمْ يُولَدْ', 'لَمۡ يَلِدۡ   ۙ وَلَمۡ يُوۡلَدۡ ۙ‏'),
('s112a4', 4, 112, 'وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ', 'وَلَمۡ يَكُنۡ لَّهٗ كُفُوًا اَحَدٌ‏'),
('s113a1', 1, 113, ' قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ', 'قُلۡ اَعُوۡذُ بِرَبِّ الۡفَلَقِۙ‏'),
('s113a2', 2, 113, 'مِن شَرِّ مَا خَلَقَ', 'مِنۡ شَرِّ مَا خَلَقَۙ‏'),
('s113a3', 3, 113, 'وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ', 'وَمِنۡ شَرِّ غَاسِقٍ اِذَا وَقَبَۙ‏'),
('s113a4', 4, 113, 'وَمِن شَرِّ ٱلنَّفَّـٰثَـٰتِ فِى ٱلْعُقَدِ', 'وَمِنۡ شَرِّ النَّفّٰثٰتِ فِى الۡعُقَدِۙ‏'),
('s113a5', 5, 113, 'وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ', 'وَمِنۡ شَرِّ حَاسِدٍ اِذَا حَسَدَ‏'),
('s114a1', 1, 114, ' قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ', 'قُلۡ اَعُوۡذُ بِرَبِّ النَّاسِۙ‏'),
('s114a2', 2, 114, 'مَلِكِ ٱلنَّاسِ', 'مَلِكِ النَّاسِۙ‏'),
('s114a3', 3, 114, 'إِلَـٰهِ ٱلنَّاسِ', 'اِلٰهِ النَّاسِۙ‏'),
('s114a4', 4, 114, 'مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ', 'مِنۡ شَرِّ الۡوَسۡوَاسِ  ۙ الۡخَـنَّاسِ ۙ‏'),
('s114a5', 5, 114, 'ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ', 'الَّذِىۡ يُوَسۡوِسُ فِىۡ صُدُوۡرِ النَّاسِۙ‏'),
('s114a6', 6, 114, 'مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ', 'مِنَ الۡجِنَّةِ وَالنَّاسِ‏')
